#ifdef PAL4_TEST_NATIVE_RENDERWARE
struct NativeKeyboardProbeBinder final {
    std::vector<std::pair<std::uint32_t, std::uint32_t>>& events;
    std::uint32_t kind;
    NativeKeyboardProbeBinder(decltype(events) output, std::uint32_t type)
        : events(output), kind(type) {}
    virtual bool OnEvent(const void* event) const {
        const auto* words = static_cast<const std::uint32_t*>(event);
        events.emplace_back(kind, words[kind == WM_CHAR ? 3u : 4u]);
        return true;
    }
    virtual ~NativeKeyboardProbeBinder() = default;
};

void VerifyNativeKeyboardMessages(pal4::NativeCeguiUiSession& ui, HWND window) {
    const auto module = GetModuleHandleA("CEGUIBase.dll");
    using GetSheet = void* (__thiscall*)(const void*);
    using Subscribe = void* (__thiscall*)(void*, void**, const void*, void*);
    using Remove = void (__thiscall*)(void*, const void*);
    using Release = void (__thiscall*)(void*);
    const auto get_sheet = reinterpret_cast<GetSheet>(GetProcAddress(module,
        "?getGUISheet@System@CEGUI@@QBEPAVWindow@2@XZ"));
    const auto remove = reinterpret_cast<Remove>(GetProcAddress(module,
        "?removeAllConnection@EventSet@CEGUI@@QAEXABVString@2@@Z"));
    const auto release = reinterpret_cast<Release>(GetProcAddress(module,
        "?release@Referenced@CEGUI@@QBEXXZ"));
    Check(get_sheet && remove && release, "original keyboard event subscription exports exist");
    auto* sheet = get_sheet(reinterpret_cast<const void*>(ui.SystemAddress()));
    Check(sheet != nullptr, "keyboard probe uses the real fresh desktop");
    using Activate = void (__thiscall*)(void*);
    const auto activate = reinterpret_cast<Activate>(GetProcAddress(module,
        "?activate@Window@CEGUI@@QAEXXZ"));
    Check(activate != nullptr, "original desktop internal focus activation exists");
    activate(sheet);
    const auto subscribe = reinterpret_cast<Subscribe>((*reinterpret_cast<void***>(sheet))[2]);
    const std::array names{
        "?EventKeyDown@Window@CEGUI@@2VString@2@B",
        "?EventKeyUp@Window@CEGUI@@2VString@2@B",
        "?EventCharacterKey@Window@CEGUI@@2VString@2@B"};
    const std::array kinds{WM_KEYDOWN, WM_KEYUP, WM_CHAR};
    std::vector<std::pair<std::uint32_t, std::uint32_t>> events;
    for (std::size_t i = 0; i < names.size(); ++i) {
        const auto name = GetProcAddress(module, names[i]);
        Check(name != nullptr, "original keyboard event name exists");
        void* connection = nullptr;
        subscribe(sheet, &connection, name, new NativeKeyboardProbeBinder(events, kinds[i]));
        Check(connection != nullptr, "original desktop subscribes keyboard probe");
        release(connection);
    }
    // Exercise the game mapping/remapping, not host MapVirtualKey defaults.
    for (const auto key : {UINT('W'), UINT('A'), UINT('S'), UINT('D'), UINT(VK_SPACE)}) {
        const bool down = ui.ProcessKeyboardMessage(window, WM_KEYDOWN, key, 0u);
        const bool up = ui.ProcessKeyboardMessage(window, WM_KEYUP, key, 0u);
        if (!down || !up)
            std::cerr << "Keyboard probe key=" << key << " down=" << down
                      << " up=" << up << " events=" << events.size() << '\n';
        Check(down && up, "native keyboard down/up reaches original DLL subscribers");
    }
    Check(!ui.ProcessKeyboardMessage(window, WM_KEYDOWN, VK_ESCAPE, 0u),
          "original Escape down is deferred");
    Check(ui.ProcessKeyboardMessage(window, WM_KEYUP, VK_ESCAPE, 0u) &&
              ui.ProcessKeyboardMessage(window, WM_CHAR, 0x4e2du, 0u),
          "Escape release and Unicode character reach original DLL");
    const std::vector<std::pair<std::uint32_t, std::uint32_t>> expected{
        {WM_KEYDOWN,200u},{WM_KEYUP,200u}, {WM_KEYDOWN,203u},{WM_KEYUP,203u},
        {WM_KEYDOWN,208u},{WM_KEYUP,208u}, {WM_KEYDOWN,205u},{WM_KEYUP,205u},
        {WM_KEYDOWN,28u},{WM_KEYUP,28u}, {WM_KEYDOWN,1u},{WM_KEYUP,1u},
        {WM_CHAR,0x4e2du}};
    Check(events == expected, "original DLL observes exact mapped keys, Escape order and Unicode");
    // This is a fresh desktop before any game subscriptions are installed.
    for (const auto name : names) remove(sheet, GetProcAddress(module, name));
    std::cout << "Native CEGUI keyboard mapping, Escape release and Unicode events verified\n";
}
#endif

RECT CheckSecondaryWindowBounds(HWND window) {
    MONITORINFOEXA display{};
    display.cbSize = sizeof(display);
    const bool display_found =
        GetMonitorInfoA(MonitorFromWindow(window, MONITOR_DEFAULTTONULL),
                        &display) != FALSE;
    if (!display_found || std::string_view(display.szDevice) !=
                              pal4::test::TestDisplay().device) {
        RECT actual{};
        (void)GetWindowRect(window, &actual);
        std::cerr << "1600x900 secondary screen check: found=" << display_found
                  << " device=" << display.szDevice
                  << " monitor=" << display.rcMonitor.left << ','
                  << display.rcMonitor.top << ',' << display.rcMonitor.right
                  << ',' << display.rcMonitor.bottom << " window="
                  << actual.left << ',' << actual.top << ',' << actual.right
                  << ',' << actual.bottom << '\n';
    }
    Check(display_found &&
              std::string_view(display.szDevice) == pal4::test::TestDisplay().device &&
              (display.dwFlags & MONITORINFOF_PRIMARY) == 0u &&
              display.rcMonitor.right - display.rcMonitor.left == 1600 &&
              display.rcMonitor.bottom - display.rcMonitor.top == 900,
          "test game window opens on the secondary 1600x900 screen");
    RECT window_rect{};
    Check(GetWindowRect(window, &window_rect) != FALSE &&
              window_rect.left >= display.rcMonitor.left &&
              window_rect.top >= display.rcMonitor.top &&
              window_rect.right <= display.rcMonitor.right &&
              window_rect.bottom <= display.rcMonitor.bottom,
          "test game window stays within secondary display");
    std::cout << "Native test window display=" << display.szDevice
              << " mode=1600x900 nonprimary window="
              << window_rect.left << ',' << window_rect.top << ','
              << window_rect.right << ',' << window_rect.bottom << '\n';
    return display.rcMonitor;
}

