std::optional<bool> DdsDxt5HasAlpha(std::span<const std::uint8_t> bytes) {
    if (bytes.size() < 128u ||
        std::memcmp(bytes.data(), "DDS ", 4u) != 0 ||
        std::memcmp(bytes.data() + 84u, "DXT5", 4u) != 0)
        return std::nullopt;
    std::uint32_t width = 0u;
    std::uint32_t height = 0u;
    std::memcpy(&height, bytes.data() + 12u, sizeof(height));
    std::memcpy(&width, bytes.data() + 16u, sizeof(width));
    if (width == 0u || height == 0u) return std::nullopt;
    const auto blocks_x = (static_cast<std::uint64_t>(width) + 3u) / 4u;
    const auto blocks_y = (static_cast<std::uint64_t>(height) + 3u) / 4u;
    if (blocks_x * blocks_y > (bytes.size() - 128u) / 16u)
        return std::nullopt;
    for (std::uint64_t by = 0u; by < blocks_y; ++by) {
        for (std::uint64_t bx = 0u; bx < blocks_x; ++bx) {
            const auto* block = bytes.data() + 128u +
                                (by * blocks_x + bx) * 16u;
            std::array<std::uint8_t, 8u> alpha{block[0], block[1]};
            if (alpha[0] > alpha[1]) {
                for (int index = 2; index < 8; ++index)
                    alpha[index] = static_cast<std::uint8_t>(
                        ((8 - index) * alpha[0] +
                         (index - 1) * alpha[1]) / 7);
            } else {
                for (int index = 2; index < 6; ++index)
                    alpha[index] = static_cast<std::uint8_t>(
                        ((6 - index) * alpha[0] +
                         (index - 1) * alpha[1]) / 5);
                alpha[6] = 0u;
                alpha[7] = 255u;
            }
            std::uint64_t selectors = 0u;
            for (int index = 0; index < 6; ++index)
                selectors |= static_cast<std::uint64_t>(block[2 + index])
                             << (8 * index);
            for (std::uint32_t y = 0u; y < 4u && by * 4u + y < height; ++y) {
                for (std::uint32_t x = 0u; x < 4u && bx * 4u + x < width;
                     ++x) {
                    const auto selector =
                        (selectors >> (3u * (4u * y + x))) & 7u;
                    if (alpha[selector] != 255u) return true;
                }
            }
        }
    }
    return false;
}

std::vector<std::uint8_t> ReadFileBytes(const std::filesystem::path& path) {
    std::ifstream input(path, std::ios::binary);
    Check(static_cast<bool>(input), "open original or isolated pal4.set");
    return {std::istreambuf_iterator<char>(input),
            std::istreambuf_iterator<char>()};
}
