struct WindowNewGameLoadHost final : pal4::PlayerManagerLoadRuntimeStub {
    explicit WindowNewGameLoadHost(std::uint32_t manager,
                                   std::uint32_t database)
        : manager(manager), database(database) {}
    std::uint32_t GameDB() override { return database; }
    std::uint32_t ReadDword(std::uint32_t address) override {
        if (address < manager ||
            address >= manager +
                pal4::PlayerManagerObject::kElementCount *
                    pal4::PlayerManagerSlot::kObjectBytes)
            throw std::invalid_argument("PAL4 NewGame player address");
        return *reinterpret_cast<const std::uint32_t*>(address);
    }
    void CallLoadActor(std::uint32_t slot, std::uint32_t virtual_slot,
                       std::uint32_t, std::uint32_t model,
                       std::uint32_t enabled) override {
        if (slot < manager ||
            (slot - manager) % pal4::PlayerManagerSlot::kObjectBytes != 0u ||
            virtual_slot != 0x30u || model == 0u || enabled != 1u)
            throw std::invalid_argument("PAL4 NewGame actor load arguments");
        loaded_models.emplace_back(reinterpret_cast<const char*>(model));
    }
    void ProcessLoadedData(std::uint32_t) override {
        throw std::logic_error("PAL4 player postprocess is not bound");
    }
    void ProcessScripts() override {
        throw std::logic_error("PAL4 player script scope requires PK manager");
    }
    void CleanupScripts() override {
        throw std::logic_error("PAL4 player script cleanup requires PK manager");
    }
    std::uint32_t manager;
    std::uint32_t database;
    std::vector<std::string> loaded_models;
};

