    pal4::NativeSystemMenuDecorations* decorations = nullptr;
    std::uint32_t manager{};
    std::uint32_t ReadDword(std::uint32_t address) override {
        return *reinterpret_cast<std::uint32_t*>(
            static_cast<std::uintptr_t>(address));
    }
