    std::array<std::uint32_t, 3> ColdPlayerPosition() const {
        const auto& player = native_player_session->State().slots[0].base;
        return {player.Read(0xacu), player.Read(0xb0u), player.Read(0xb4u)};
    }
    void PrepareColdInputFrame() {
        if (loaded_scene_frames == 0u) {
            std::cout<<"Cold input HUD prerequisite: arena_ready="<<native_arena_manager->ReadyFlag()
                     <<" scene_init="<<static_cast<int>(native_script_session->ConcurrentSceneStatus())<<'\n';
            // Loading queues the initializer. The HUD/signpost fixture below
            // renders real Scene frames, whose original ArenaReady guard must
            // already be open. Finish actual nonblocking source steps first.
            if(native_arena_manager->ReadyFlag()!=1u)CompleteNonblockingSceneInitProbe();
            Check(native_arena_manager->ReadyFlag()==1u,"cold input HUD fixture has naturally initialized ArenaReady");
            const auto scenario_parent = [this] {
                const auto root = *reinterpret_cast<const std::uint32_t*>(
                    native_ui.ScenarioActiveComponentAddress() - 4u);
                return *reinterpret_cast<const std::uint32_t*>(root + 68u);
            };
            Check(!native_ui.HasScenarioDialogLayout() && native_script_talk,
                  "cold archive has not borrowed NewGame scenario dialog setup");
            const auto manager = native_script_talk->UiFrameManager();
            Check(native_script_talk->CreateScenarioDialog(manager) == manager &&
                      native_ui.HasScenarioDialogLayout() && !native_ui.ScenarioDialogVisible() &&
                      scenario_parent() == 0u,
                  "cold archive first script dialog request lazily creates original DLL layout");
            Check(native_script_talk->CreateScenarioDialog(manager) == manager &&
                      native_script_talk->SetText(manager, "Cold archive dialogue",
                          pal4::ScriptTalkHandler::kDisplayValue) == 1u &&
                      native_ui.ScenarioDialogVisible() && scenario_parent() != 0u &&
                      native_ui.HideScenarioDialog() && scenario_parent() == 0u,
                  "cold archive repeated dialog request reuses layout and displays text");
            VerifyNativeGlobalHudInput(reinterpret_cast<HWND>(game.Read(0u)));
        }
        if (loaded_scene_frames == 6u) {
            cold_input_start = ColdPlayerPosition();
            const auto actor = reinterpret_cast<std::uint32_t>(
                &native_player_session->State().slots[0].base);
            cold_input_idle_action = native_script_player_action->CurrentRecordName(actor);
            auto* camera = reinterpret_cast<RwCamera*>(native_camera_manager->ActiveCameraPointer());
            cold_input_camera_start = *RwMatrixGetPos(RwFrameGetLTM(RwCameraGetFrame(camera)));
        }
        const bool held = loaded_scene_frames >= 6u && loaded_scene_frames < 18u;
        ActiveInput().WriteDword(0x1f38u, held ? 1u : 0u);
        ActiveInput().WriteDword(0x1f44u, held ? 1u : 0u);
    }
    void VerifyColdInputFrame() {
        const auto position = ColdPlayerPosition();
        auto& control = native_actor_session->State();
        const auto actor = reinterpret_cast<std::uint32_t>(
            &native_player_session->State().slots[0].base);
        const auto action = native_script_player_action->CurrentRecordName(actor);
        if (loaded_scene_frames == 18u) {
            cold_input_stop = position;
            std::cout << "Cold input held: control=" << control.words[0]
                      << " mode=" << control.words[28] << " moving=" << control.words[27]
                      << " action=" << native_script_player_action->CurrentRecordName(
                          reinterpret_cast<std::uint32_t>(&native_player_session->State().slots[0].base)) << '\n';
            Check(position != cold_input_start,
                  "cold saved player moves during twelve held-input scene frames");
            Check(control.words[27] != 0u && action != cold_input_idle_action,
                  "cold saved movement enters a movement animation");
        }
        if (loaded_scene_frames == 24u) {
            Check(position == cold_input_stop && control.words[27] == 0u,
                  "cold saved player stops for six released-input scene frames");
            Check(action == cold_input_idle_action,
                  "cold saved movement restores its original idle animation");
            auto* camera = reinterpret_cast<RwCamera*>(native_camera_manager->ActiveCameraPointer());
            const auto camera_position = *RwMatrixGetPos(RwFrameGetLTM(RwCameraGetFrame(camera)));
            Check(std::isfinite(camera_position.x) && std::isfinite(camera_position.y) &&
                      std::isfinite(camera_position.z) &&
                      (camera_position.x != cold_input_camera_start.x ||
                       camera_position.y != cold_input_camera_start.y ||
                       camera_position.z != cold_input_camera_start.z),
                  "cold saved camera follows movement with finite SDK coordinates");
            cold_input_verified = true;
            std::cout << "Cold saved input: HUD R/M, twelve held frames and six stopped frames verified\n";
        }
    }
