            Check(item.Clump()!=nullptr,"owned UI scene loads original Property component");
            item.SetBaseRotation({30.0f,10.0f,0.0f});
            item.SetPosition({-59.669998f,349.85999f,298.26001f});
            item.SetRotationRates(true,{0.0f,50.0f,0.0f});
            const auto item_before=*RwFrameGetMatrix(RpClumpGetFrame(item.Clump()));
            (void)native_ui_frame_update->Update(0.125);
