    void EnsurePersistentSystemSettings() {
        if(native_persistent_settings)return;
        Check(native_persistent_system_pages && native_system_setting_stats && native_background_music_runtime &&
                  native_hud_sounds && native_ui_sound_playback,
              "persistent settings borrow actual live game/audio owners");
        const auto manager=UiFrameManagerAddress();
        pal4::NativeSystemSettingSessionServices services;
        PrepareNativeSystemArchiveRoot();
        services.archive_root=NativeSystemArchiveRoot();
        services.event=[this,manager](auto tree,auto key,auto first,auto second){
            Check(tree==manager+260u,"persistent settings event manager");native_persistent_system_pages->Event(key,first,second);};
        services.tutorial=[this](auto key){native_ui.ShowTutorial(native_database,native_settings->State(),*native_settings_writer,
            native_game_texture_storage->Address(),key);};
        services.quit=pal4::BindNativeSystemQuitToLogo(*native_arena_load,native_persistent_system_pages->Toolbar(),
            [this]{ReleaseCurrentScene();});
        services.save_slot=[this](std::int32_t slot){SaveNativeSlot(slot);};
        services.enter_loading=[this](const pal4::BinaryXmlNode& request){
            Check(!native_arena_load->SystemActive() && !native_system_archive_loading && pending_load_slot<0,
                "System load follows original B4/Scene and has no competing archive request");
            pal4::EnterNativeArchiveLoading(request,*native_arena_load);
            Check(native_arena_load->LoadingActive() && !native_arena_load->LiveDocumentCount(),
                "System confirmation consumes temporary config into actual Loading state");
            native_system_archive_loading=true;};
        services.samples=[this]{std::vector<pal4::NativeMilesSound2dRuntime*> owners;
            if(native_sound_2d)owners.push_back(native_sound_2d.get());
            if(native_hud_sounds)owners.push_back(native_hud_sounds.get());return owners;};
        native_persistent_settings=std::make_unique<pal4::NativeSystemSettingSession>(native_ui,config_path->parent_path(),
            native_database,*native_settings,*native_settings_writer,*native_system_setting_stats,*native_scene_effects,
            *native_ui_active_handlers,manager,native_arena_manager->Address(),*native_background_music_runtime,
            *native_ui_sound_playback,*native_persistent_system_warning,std::move(services));
    }
    std::unique_ptr<pal4::NativeScriptSystemUiRuntime> MakeNativeScriptSystemUiRuntime() {
        pal4::NativeScriptSystemUiServices endpoints;
        endpoints.enter_system=[this]{
            EnsurePersistentSystemMenu();
            Check(native_arena_load->TransitionToSystem(), "script enters registered System state");
        };
        endpoints.event=[this](auto key,auto first,auto second){
            Check(native_arena_load && native_arena_load->SystemActive() && native_persistent_system_pages,
                  "script menu selection follows successful System entry");
            native_persistent_system_pages->Event(key,first,second);
            native_persistent_system_pages->RethrowError();
        };
        return std::make_unique<pal4::NativeScriptSystemUiRuntime>(
            *native_game_texture_storage,UiFrameManagerAddress(),this,std::move(endpoints));
    }
