            Check(*reinterpret_cast<const unsigned*>(frame+0xe8u)==action[1] && (*reinterpret_cast<const unsigned*>(frame+0xf8u)&0xffu)==action[2],"global original buy/sell/group payloads reach native data");
            RenderPersistentTradeFrame(0.f);
