            std::cerr<<"Trade global Esc: handled="<<key<<" state4="<<native_arena_load->TradeActive()<<" trade="<<native_trade_system->State()
                <<" selector="<<native_trade_ui->Selector().Visible()<<" down="<<native_keyboard_keydown_dispatches-down_before
                <<" last="<<native_ui_active_handlers->GetLast()<<" page="<<frame+0x19cu
                <<" modal="<<pal4::detail::Export<void* (__thiscall*)(const void*)>(GetModuleHandleA("CEGUIBase.dll"),"?getModalTarget@System@CEGUI@@QBEPAVWindow@2@XZ")(reinterpret_cast<void*>(native_ui.SystemAddress()))<<'\n';
            Check(native_keyboard_keydown_dispatches==down_before+1u && native_arena_load->TradeActive() && !native_trade_system->State() && native_trade_ui->Selector().Visible(),"global Esc closes actual page, restores scene music and returns real selector without leaving Trade");
            RenderPersistentTradeFrame(0.f);
