        (void)native_ui.ProcessKeyboardMessage(hwnd,WM_KEYUP,VK_ESCAPE,static_cast<LPARAM>(0xc0010001u));
        Check(native_keyboard_keydown_dispatches==down_before+1u && !native_arena_load->TradeActive() && native_trade_system->State()==2u && !native_trade_ui->Selector().Visible(),"selector exit uses original Trade-to-Scene then state2 ordering");
