    std::uint32_t VerifyRegisteredPlayerCombat(){
        unsigned commands{},magic_commands{},property_commands{},ends{},frames{};
        pal4::test::NativeCombatPlayerInputPolicy input_policy(native_inventory,*native_skill_catalog,*native_combat_monsters);
        std::vector<pal4::NativeCombatActorSkillRuntime*> input_players;for(auto& s:native_combat_player_skills)input_players.push_back(s.get());
        pal4::test::ReportNativeCombatPlayerInitialStats(input_players);
        std::optional<std::uint32_t> natural_outcome;
        const auto configuration=native_combat_config.Snapshot();
        const bool scripted_round_limit=static_cast<std::int32_t>(configuration.words[0])>0 && configuration.words[1] && configuration.words[4]==2u;
        bool original_round_condition{};
        struct TraceRoutes{pal4::NativeScriptEventRouter& r;std::vector<std::uint32_t> tokens;~TraceRoutes(){for(auto t:tokens)(void)r.Unsubscribe(t);}} trace{native_combat_events};
        unsigned trace_count{};
        for(const auto name:{"re_can_take_action","me_can_take_action","re_start_ui_control","combat_over","ae_state_changed"})
            trace.tokens.push_back(native_combat_events.Subscribe(native_combat_events.Key(name),3u,[&,name](std::uint32_t payload){
                if(std::string_view(name)=="combat_over"){
                    natural_outcome=*reinterpret_cast<const std::uint32_t*>(payload);
                    if(scripted_round_limit && natural_outcome==2u){
                        for(std::size_t i=0;i<native_combat_monsters->Count();++i){auto& skills=native_combat_monsters->Skills(native_combat_monsters->ActorAt(i));
                            if(static_cast<std::uint32_t>(skills.AiTargetId())==configuration.words[1] && static_cast<std::uint32_t>(skills.TurnCount())==configuration.words[0])original_round_condition=true;}
                    }
                    std::cout<<"Native natural combat_over: result="<<*natural_outcome<<"; actor outcome event, before deferred EndSequence commit"<<std::endl;
                }
                if(trace_count++<30u)std::cout<<"Natural Combat event: "<<name<<" payload="<<payload<<" state="<<native_combat_image.State()<<std::endl;
            }));
        const auto is_player=[this](std::uint32_t actor){
            for(std::size_t n=0;n<native_combat_players->Count();++n)
                if(native_combat_players->ActorAt(n)==actor)return true;
            return false;
        };
        const auto command_token=native_combat_events.Subscribe(native_combat_events.Key("re_select_command"),3u,[&](std::uint32_t p){
            const auto* words=reinterpret_cast<const std::uint32_t*>(p);
            if(words && words[0]>=716u && is_player(words[0]-716u) && (words[3]==0u || words[3]==2u || words[3]==4u || words[3]==5u)){++commands;if(words[3]==0u)++magic_commands;if(words[3]==2u)++property_commands;}
        });
        const auto end_token=native_combat_events.Subscribe(native_combat_events.Key("ae_end_action"),3u,[&](std::uint32_t p){
            const auto facet=*reinterpret_cast<const std::uint32_t*>(p);
            if(facet>=716u && is_player(facet-716u))++ends;
        });
        struct Routes{pal4::NativeScriptEventRouter& r;std::uint32_t a,b;~Routes(){(void)r.Unsubscribe(a);(void)r.Unsubscribe(b);}}
            routes{native_combat_events,command_token,end_token};
        const auto key=[this](std::uint32_t code){
            std::array<std::uint32_t,5> event{};event[4]=code;
            return native_ui_active_handlers->DispatchKeyDown(native_ui_active_handlers->GetLast(),reinterpret_cast<std::uint32_t>(event.data()));
        };
        while(native_arena_load->CombatActive() && native_combat_image.State()>=2u && native_combat_image.State()<=5u && frames<18000u){
            if(native_ui.TutorialVisible()){
                const auto hwnd=reinterpret_cast<HWND>(game.Read(0u));
                (void)native_ui.ProcessKeyboardMessage(hwnd,WM_KEYDOWN,VK_ESCAPE,0u);
                (void)native_ui.ProcessKeyboardMessage(hwnd,WM_KEYUP,VK_ESCAPE,0u);native_ui.RethrowTutorialError();
            }else if(native_combat_action_window->Word(88u) && (native_ui_active_handlers->GetLast()==native_combat_action_window->Address()+40u ||
                     native_combat_action_controller->OwnsSelectorActivity(native_ui_active_handlers->GetLast()))){
                (void)key(input_policy.NextPlayerKey(*native_combat_action_controller,*native_combat_action_window,
                    *native_ui_active_handlers,input_players,*native_combat_magic_stunt_records,scripted_round_limit));
            }else if(native_combat_image.State()==5u && native_combat_target_selection->CurrentActor() &&
                     native_ui_active_handlers->GetLast()==native_combat_main_session->InputAddress()){
                (void)key(input_policy.NextTargetKey(*native_combat_target_selection));
            }
            RenderPersistentCombatFrame(1.0/60.0);++frames;
            if(frames%600u==0u){
                std::cout<<"Native registered Player combat: frames="<<frames<<" state="<<native_combat_image.State()
                    <<" magic_commands="<<magic_commands<<" mode="<<unsigned(native_combat_image.Mode())<<" scheduler_active="<<native_combat_system_manager->Active()<<" objects="<<native_combat_system_manager->Objects().size()<<" commands="<<commands<<" ends="<<ends
                    <<" action_actor="<<native_combat_action_window->Word(88u)<<" activity="<<native_ui_active_handlers->GetLast()
                    <<" target="<<native_combat_target_selection->CurrentActor()<<" tasks="<<native_combat_task_queue->Count()<<std::endl;
                for(auto& skill:native_combat_player_skills)std::cout<<"Player natural progress: actor="<<skill->ActorAddress()
                    <<" hp="<<skill->CurrentStat(7u)<<" progress="<<skill->ActionProgress()<<" action="<<skill->ActionState()<<" primary="<<skill->PrimaryMotionState()<<" secondary="<<skill->SecondaryMotionState()<<" ready="<<skill->ReadyForAction()<<std::endl;
            }
        }
        if(native_combat_image.State()==6u && natural_outcome==0u){
            unsigned defeat_frames{};
            while(native_arena_load->CombatActive() && defeat_frames<600u){RenderPersistentCombatFrame(1.0/60.0);++defeat_frames;}
            unsigned game_over_frames{};
            while(native_arena_load->GameOverActive() && game_over_frames<360u){(void)AdvancePersistentGameOverFrameIfActive(1.0/60.0);++game_over_frames;}
            Check(native_arena_load->LogoActive() && !native_game_over->Entered() && !native_game_over->Texture() &&
                  native_game_over->DrawCount()>200u && native_game_over->LastAlpha()<=2 && !native_combat_players->Count() && !native_combat_monsters->Count() &&
                  native_game_over_gpu_energy[0]>100000u && native_game_over_gpu_energy[0]>native_game_over_gpu_energy[1] && native_game_over_gpu_energy[1]>native_game_over_gpu_energy[2],
                  "natural defeat closes Combat, draws/fades actual GameOver texture and returns Logo without live roster");
            std::cout<<"Native natural GameOver loop: frames="<<game_over_frames<<" draws="<<native_game_over->DrawCount()
                <<" alpha="<<native_game_over->LastAlpha()<<" Logo0=1 actors=0; natural victory remains separate"<<std::endl;
            std::cout<<"Native natural defeat: battle_frames="<<frames<<" close_frames="<<defeat_frames
                <<" active="<<native_arena_load->CombatActive()<<" state="<<native_combat_image.State()
                <<" result="<<native_combat_image.session_storage[27]<<"; original result retained, victory gate remains required"<<std::endl;
        }
        if(!(commands && ends && native_combat_image.State()==6u && (scripted_round_limit?(natural_outcome==2u && original_round_condition):natural_outcome==1u)))
            throw std::runtime_error("required natural combat outcome remains unverified; observed defeat completed GameOver/Logo lifecycle");
        std::cout<<"Native registered Player combat outcome: frames="<<frames<<" commands="<<commands<<" ends="<<ends<<" result="<<*natural_outcome
            <<" magic_commands="<<magic_commands<<" property_commands="<<property_commands<<" scripted_round_limit="<<scripted_round_limit<<" original_round_condition="<<original_round_condition
            <<"; actual DLL numeric/target input, no HP/phase/result writes or quick_end injection; result2 is scripted completion, not natural victory"<<std::endl;
        return *natural_outcome;
    }
