    void RenderPersistentSystemFrame(double elapsed) {
        Check(native_arena_load->SystemActive() && native_persistent_system_pages,"persistent System frame has live session");
        (void)native_arena_load->UpdateSystem(static_cast<float>(elapsed),0u,0u);
        native_persistent_system_pages->RethrowError();
        if(native_persistent_settings)native_persistent_settings->RethrowError();
        auto* camera=reinterpret_cast<RwCamera*>(native_camera_manager->ActiveCameraPointer());RwRGBA clear{0,0,0,255};
        Check(RwCameraClear(camera,&clear,rwCAMERACLEARIMAGE|rwCAMERACLEARZ) && RwCameraBeginUpdate(camera),"begin persistent System frame");
        (void)native_arena_load->RenderSystem(reinterpret_cast<std::uint32_t>(&camera));
        Check(RwCameraEndUpdate(camera),"end persistent System frame");
        pal4::NativeRenderWarePresentation presentation;
        const auto address=reinterpret_cast<std::uint32_t>(camera);
        pal4::test::NativeFramePresentationStatusProbe probe;
        const auto shown=pal4::GameRenderSystem(game).ShowGameRaster(address,presentation);
        if(shown!=address)probe.ReportFailure("System",camera);
        Check(shown==address,"present persistent System frame");
    }
