    class PalTestRuntime final : public pal4::IScriptPalTestResultRuntime {
    public:
        explicit PalTestRuntime(Services& owner) : owner_(owner) {}
        std::uint32_t GlobalData() override { return 0x1000u; }
        std::uint32_t ReadWord(std::uint32_t address) override {
            Check(owner_.native_settings && address >= 0x101cu && address <= 0x1024u && address % 4u == 0u,
                  "PalTest reads original live GlobalData result fields");
            return owner_.native_settings->State().Word(address - GlobalData());
        }
    private:
        Services& owner_;
    } native_pal_test{*this};
