    void VerifyNativeLoadKeyboardNavigation() {
        const auto hwnd=reinterpret_cast<HWND>(game.Read(0u));
        const auto click=[&](int x,int y){const auto point=MAKELPARAM(x,y);
            for(const auto message:{WM_MOUSEMOVE,WM_LBUTTONDOWN,WM_LBUTTONUP})
                Check(native_menu->ProcessMouseMessage(hwnd,message,message==WM_LBUTTONDOWN?MK_LBUTTON:0u,point),"Load keyboard fixture uses original controls");};
        const auto key=[&](unsigned value){(void)native_ui.ProcessKeyboardMessage(hwnd,WM_KEYDOWN,value,0u);
            (void)native_ui.ProcessKeyboardMessage(hwnd,WM_KEYUP,value,0u);};
        click(90,420); // Explicit first page, independently of saved UI settings.
        const auto activity_count=native_ui_active_handlers->Size();
        Check(activity_count && native_menu->OwnsActivity(native_ui_active_handlers->GetLast()),"shown Load owns the top active input component");
        key(VK_UP);key(VK_LEFT);
        Check(native_ui.CurrentLoadPage()==0 && native_menu->HoveredLoadSlot()==0,"Load upper/left bounds retain page0 row0");
        for(unsigned n=0;n<4;++n)key(VK_DOWN);
        Check(native_menu->HoveredLoadSlot()==4,"Load Down traverses the visible fourth-card boundary");
        for(unsigned n=0;n<4;++n)key(VK_UP);
        Check(native_menu->HoveredLoadSlot()==0,"Load Up returns to first card");
        for(unsigned n=0;n<10;++n)key(VK_RIGHT);
        Check(native_ui.CurrentLoadPage()==9 && native_menu->HoveredLoadSlot()==90,"Load Right stops at last page and publishes its real row IDs");
        for(unsigned n=0;n<10;++n)key(VK_LEFT);
        Check(native_ui.CurrentLoadPage()==0 && native_menu->HoveredLoadSlot()==0 && native_menu->PageSummaries()[0],"Load Left returns to valid page0 metadata");
        key(VK_RETURN);
        Check(native_menu->LoadConfirmationVisible() && !native_menu->TakeAction(),"Load Enter opens confirmation without loading");
        key(VK_ESCAPE);
        Check(!native_menu->LoadConfirmationVisible() && !native_menu->TakeAction() &&
            native_ui_active_handlers->Size()==activity_count,"modal Escape preserves Load activity without loading");
        key(VK_ESCAPE);
        Check(native_ui_active_handlers->Size()+1u==activity_count,"list Escape removes its activity and restores Logo");
        click(100,400);
        Check(native_ui_active_handlers->Size()==activity_count && native_menu->OwnsActivity(native_ui_active_handlers->GetLast()),"Load can reopen after keyboard close without duplicate activity");
        native_load_keyboard_verified=true;
        std::cout<<"Load keyboard: actual DLL Up/Down/card scroll, Left/Right page0..9 bounds, Enter/No, Escape and reopen pass\n";
    }
    std::uint32_t native_ui_hover_count = 0u;
