    void EnsureNativeSceneEffects() {
        if (!native_scene_effects) {
            Check(config_path && native_packages, "native effect session has original package services");
            native_scene_effects=std::make_unique<pal4::NativeEffectSceneSession>(
                config_path->parent_path(),*native_packages);
            // The original effect registration is a singleton. Run this isolated
            // composition before any Scene/UI payload binds to the new session.
            if(input_load_smoke){
                Check(native_player_session && native_player_session->Constructed() && native_skill_system,
                    "exit probe borrows constructed Player/Skill owners before first scene effects");
                pal4::test::VerifyNativeCombatActorExit(config_path->parent_path(),*native_player_session,
                    native_database,*native_skill_system,*native_scene_effects);
                pal4::test::VerifyLoadedCombatPlayerPropertySkills(*native_player_session,native_inventory,
                    native_database,*native_skill_system);
            }
            BindNativeCombatFacetReader();
            Check(native_settings != nullptr, "scene effects require loaded settings");
            pal4::GlobalDataSettingsState settings;
            static_cast<void>(pal4::GlobalDataSettings::ApplyScaleOption(
                settings, native_settings->State().Word(12u), *native_scene_effects));
        }
        native_scene_effects->BindSound(native_hud_sounds.get());
        native_monster_scene_entry.BindAttachedEffectRuntime(&native_scene_effects->AttachedEffects());
        if (CurrentSceneNpcs())
            CurrentSceneNpcs()->BindAttachedEffectRuntime(&native_scene_effects->AttachedEffects());
        native_scene_effects->BindActors(native_script_player_position.get());
        if(native_camera_manager)
            native_scene_effects->BindCamera(native_camera_manager->ActiveCameraPointer());
        if(native_arena_manager && native_arena_manager->Address())
            native_scene_effects->BindArena(native_arena_manager->Address());
        if (!native_pet_scene && native_pet && native_player_session && native_arena_scene_stage &&
            native_arena_world.World())
            native_pet_scene = std::make_unique<pal4::NativePetSceneSession>(
                config_path->parent_path(), *native_pet, *native_pet_activity,
                native_pet_memory, native_pet_animation, game.Address(),
                native_arena_manager->Address(), native_arena_scene_stage->CollisionTree(),
                *native_packages, *native_scene_effects, native_player_transforms,
                native_player_session->Address());
        if (!native_npc_hands && CurrentSceneNpcs() && native_script_object_visibility && native_arena_world.World())
            native_npc_hands=std::make_unique<pal4::NativeNpcHandSession>(
                *CurrentSceneNpcs(),native_scene_gob_assets,*native_script_object_visibility,
                *native_arena_world.World(),game.Address(),*native_scene_effects,native_player_transforms);
        if (native_arena_world.World() && native_player_session && native_script_player_action) {
            if (!native_player_equipment_scene)
                native_player_equipment_scene=std::make_unique<pal4::NativePlayerEquipmentSession>(
                    config_path->parent_path(),*native_arena_world.World(),game.Address(),
                    native_player_session->State(),native_inventory,*native_packages,
                    *native_scene_effects,native_player_transforms);
            native_script_player_action->BindEquipment(native_player_equipment_scene.get());
            if (!native_player_gob_attachment && native_script_object_visibility)
                native_player_gob_attachment=std::make_unique<pal4::NativePlayerGobAttachmentRuntime>(
                    *native_player_session,*native_player_equipment_scene,native_scene_gob_assets,
                    *native_script_object_visibility);
            if(native_player_reset_effects)
                native_player_reset_effects->BindEquipment(native_player_equipment_scene.get());
        }
    }
    void OpenWeather(std::int32_t type) override {
        Check(native_scene_effects && native_actor_session,"script weather owners are ready");
        native_scene_effects->SelectWorldWeather(type,*native_actor_session);
    }
    void CloseWeather() override {
        Check(native_scene_effects != nullptr,"script weather effect owner is ready");
        native_scene_effects->StopWorldWeather();
    }
    void VerifyNativeWorldWeather() {
        Check(native_scene_effects && native_actor_session && native_camera_manager,
              "world weather fixture has actual effect, controller and camera owners");
        auto* arena = reinterpret_cast<std::uint32_t*>(native_arena_manager->Address());
        Check(!arena[103u] && !arena[105u], "world weather fixture starts without weather owners");
        pal4::NativeAngelScriptEngine engine;
        std::string source="void Stop() { giCloseWeather(); giCloseWeather(); } ";
        for(int type=-1;type<=10;++type)
            source+="void Weather"+std::to_string(type+1)+"() { giOpenWeather("+std::to_string(type)+"); } ";
        Check(engine.Raw()->AddScriptSection("weather_probe","weather_probe.cs",source.data(),source.size())>=0 &&
                  engine.Raw()->Build("weather_probe")>=0,"compile all weather callback probes");
        pal4::NativeGameScriptServices weather_services{};weather_services.weather=this;
        pal4::NativeGameScriptCallbacks callbacks(weather_services);engine.SetCallbacks(&callbacks);
        pal4::NativeScriptFrameRunner runner(engine);
        const auto run=[&](const std::string& function) {
            runner.Queue("weather_probe",function.c_str());
            Check(runner.Tick(0.0f)==pal4::NativeScriptFrameStatus::finished && runner.Error().empty(),
                  "compiled VM weather callback completes without suspending story context");
        };
        const auto active_before = native_scene_effects->ActiveCount();
        const auto pending_before = native_scene_effects->PendingCount();
        const auto first = native_scene_effects->GobEffects().Create("foot_2", 0xffffffffu, false);
        Check(first.second != 0u, "weather replacement fixture creates first-slot Dialog");
        arena[102u] = first.first; arena[103u] = first.second;
        const auto initial_words = std::array<std::uint32_t, 4>{arena[102u], arena[103u], arena[104u], arena[105u]};
        for (const auto invalid : {-1, 10}) {
            run("Weather"+std::to_string(invalid+1));
            Check(initial_words == std::array<std::uint32_t, 4>{arena[102u], arena[103u], arena[104u], arena[105u]} &&
                      native_scene_effects->ActiveCount() == active_before + 1u &&
                      native_scene_effects->PendingCount() == pending_before,
                  "invalid weather type leaves both original handles and playback unchanged");
        }
        const auto active_camera = native_camera_manager->State().At(0x30u);
        auto& data = native_camera_manager->CameraDataForObject(active_camera);
        const std::array<float, 3> eye{std::bit_cast<float>(data.At(116u)),
            std::bit_cast<float>(data.At(120u)), std::bit_cast<float>(data.At(124u))};
        for (std::int32_t type = 0; type < 10; ++type) {
            run("Weather"+std::to_string(type+1));
            const pal4::EffectSystemHandleWords handle{arena[104u], arena[105u]};
            Check(arena[102u] == 0xffffffffu && !arena[103u] && handle.system &&
                      pal4::EffectHandle::DialogNeedsUpdate(handle, native_scene_effects->ContentHandles()),
                  "each original weather creates an active Dialog and retires previous slot");
            native_scene_effects->SyncWorldWeather(*native_camera_manager);
            const auto frame = pal4::EffectHandle::GetFrame(handle, native_scene_effects->ContentHandles());
            Check(frame != 0u, "weather Dialog owns an actual SDK frame");
            const auto* matrix = RwFrameGetMatrix(reinterpret_cast<RwFrame*>(frame));
            Check(std::abs(matrix->pos.x - eye[0]) < 0.001f &&
                      std::abs(matrix->pos.y - eye[1]) < 0.001f &&
                      std::abs(matrix->pos.z - eye[2]) < 0.001f,
                  "weather SDK frame follows active CameraData eye rather than SDK camera field offsets");
            std::cout << "Native weather type=" << type << " frame=" << frame << '\n';
        }
        Check(native_scene_effects->ActiveCount() == active_before + 1u &&
                  native_scene_effects->PendingCount() == pending_before + 10u,
              "weather replacement defers previous Dialogs using actual pending tree");
        run("Stop");
        Check(native_scene_effects->ActiveCount() == active_before &&
                  native_scene_effects->PendingCount() == pending_before + 11u &&
                  arena[104u] == 0xffffffffu && !arena[105u],
              "weather stop retires final Dialog before global effect cleanup");
        native_scene_effects->StopWorldWeather();
        Check(native_scene_effects->ActiveCount() == active_before &&
                  native_scene_effects->PendingCount() == pending_before + 11u,
              "repeated weather stop does not enqueue duplicate Dialogs");
        std::cout << "Native world weather: all ten original resources, camera follow, two-slot replacement, "
                     "invalid selection and repeated stop verified\n";
    }
    void VerifyNativeSceneRenderBindingRelease() {
        Check(native_arena_scene_stage && native_arena_world.World(),
              "render-binding release fixture requires an actual loaded scene");
        const auto arena = native_arena_manager->Address();
        auto* words = reinterpret_cast<std::uint32_t*>(arena);
        constexpr std::array<std::uint32_t, 3> clump_offsets{52u, 72u, 92u};
        std::array<std::uint32_t, 3> previous{};
        std::array<RpClump*, 3> clumps{};
        std::array<RpAtomic*, 3> atomics{};
        std::array<RpAtomicCallBackRender, 3> callbacks{};
        for (std::size_t index = 0; index < clumps.size(); ++index) {
            auto* clump = RpClumpCreate();
            auto* root = RwFrameCreate();
            auto* frame = RwFrameCreate();
            auto* atomic = RpAtomicCreate();
            auto* geometry = RpGeometryCreate(3, 1, rpGEOMETRYPOSITIONS);
            Check(clump && root && frame && atomic && geometry,
                  "render-binding release creates SDK Clump and geometry owners");
            Check(RpClumpSetFrame(clump, root) && RwFrameAddChild(root, frame) &&
                      RpAtomicSetFrame(atomic, frame) && RpAtomicSetGeometry(atomic, geometry, 0) &&
                      RpClumpAddAtomic(clump, atomic) && RpWorldAddClump(native_arena_world.World(), clump),
                  "render-binding fixture attaches actual SDK Clumps to the current world");
            (void)RpGeometryDestroy(geometry);
            callbacks[index] = RpAtomicGetRenderCallBack(atomic);
            (void)pal4::NativeRwPlugin8450Processor::ProcessClump(clump);
            Check(reinterpret_cast<std::uint32_t>(RpAtomicGetRenderCallBack(atomic)) ==
                      pal4::NativeRwPlugin8450Processor::RenderCallbackAddress(),
                  "render-binding fixture installs actual material callback wrappers");
            clumps[index] = clump; atomics[index] = atomic;
            previous[index] = words[clump_offsets[index] / 4u];
            words[clump_offsets[index] / 4u] = reinterpret_cast<std::uint32_t>(clump);
        }
        std::array<std::uint32_t, 3> buffers{}, capacities{};
        constexpr std::array<std::uint32_t, 3> queue_offsets{268u, 284u, 300u};
        for (std::size_t index = 0; index < queue_offsets.size(); ++index) {
            auto* queue = words + queue_offsets[index] / 4u;
            if (!queue[1]) {
                queue[1] = native_arena_manager->AllocateQueueBytes(16u);
                queue[3] = queue[1] + 16u;
            }
            Check(queue[3] - queue[1] >= 8u,
                  "render-binding release retains a usable native queue buffer");
            // Poisoned borrowed Atomic address must never be dereferenced by cleanup.
            *reinterpret_cast<std::uint32_t*>(queue[1]) = 0xffffffffu;
            *reinterpret_cast<std::uint32_t*>(queue[1] + 4u) = 0x3f800000u;
            queue[2] = queue[1] + 8u;
            buffers[index] = queue[1]; capacities[index] = queue[3];
        }
        const auto allocations = native_arena_manager->OutstandingAllocations();
        for (unsigned repeat = 0; repeat < 2; ++repeat) {
            native_arena_scene_stage->ReleaseRenderBindings();
            for (std::size_t index = 0; index < clumps.size(); ++index) {
                const auto* queue = words + queue_offsets[index] / 4u;
                Check(RpClumpGetWorld(clumps[index]) == nullptr &&
                          words[clump_offsets[index] / 4u] == reinterpret_cast<std::uint32_t>(clumps[index]) &&
                          queue[1] == buffers[index] && queue[2] == buffers[index] &&
                          queue[3] == capacities[index],
                      "release detaches Clump borrowers and empties all queues without destroying owners/capacity");
                const auto expected = index == 2u
                    ? reinterpret_cast<RpAtomicCallBackRender>(
                        pal4::NativeRwPlugin8450Processor::RenderCallbackAddress())
                    : callbacks[index];
                Check(RpAtomicGetRenderCallBack(atomics[index]) == expected,
                      "original release restores material callbacks only for first two optional Clumps");
            }
            Check(native_arena_manager->OutstandingAllocations() == allocations,
                  "repeated render-binding release preserves arena allocation ownership");
        }
        for (std::size_t index = 0; index < clumps.size(); ++index) {
            words[clump_offsets[index] / 4u] = previous[index];
            Check(RpClumpDestroy(clumps[index]), "render-binding fixture SDK Clumps remain owned and destroyable");
        }
        std::cout << "Native render-binding release: three SDK Clumps, exact material callback branches, "
                     "three poisoned queues, retained capacity and repeated cleanup verified\n";
    }
    void ClearNativeSceneActorControl() {
        if (!native_actor_session || !native_actor_session->Constructed() ||
            !native_scene_effects || !native_arena_manager)
            throw std::logic_error("scene actor clear owners are not ready");
        auto events = SceneUiEvents();
        pal4::ClearNativeActorControl(*native_actor_session, ActiveInput(),
            native_scene_effects->ContentHandles(), events, native_ui,
            native_arena_manager->Address());
        const auto& words = native_actor_session->State().words;
        for (const auto index : {1u, 6u, 183u, 184u, 185u, 188u, 195u, 202u,
                                 20u, 21u, 22u, 223u, 224u})
            Check(words[index] == 0u, "scene actor clear resets the original control fields");
        Check(!native_ui.JumpHintProgressVisible(), "scene actor clear hides actual jump progress");
    }
    void LeaveNativeScenePlayers(bool update_materials = true) {
        if (native_active_player_scene) {
            native_active_player_scene->Release();
            native_active_player_scene.reset();
        }
        Check(native_player_session && native_arena_scene_stage && native_player_reset_effects && native_player_materials,
              "player scene release has all persistent services");
        Check(pal4::NativeArenaPlayerRelease::LeaveAll(native_player_session->State(),
                  native_arena_manager->Address(),native_arena_scene_stage->Movement(),
                  *native_player_reset_effects,*native_player_materials,update_materials)==4u,
              "scene leave visits all four player slots before equipment and effect cleanup");
        for (const auto& slot : native_player_session->State().slots)
            Check(!slot.base.Read(0x1f0u) && !slot.base.Read(0x568u) && !slot.base.Read(0x56cu),
                  "all four players clear state and collision borrowers before scene teardown");
    }
    void ClearNativeSceneEffects() {
        native_player_gob_attachment.reset();
        if (native_npc_hands) { native_npc_hands->Clear(); native_npc_hands.reset(); }
        if (native_script_player_actions) native_script_player_actions->UnbindScene();
        if (native_pet_scene) {
            native_pet_scene->Clear();
            Check(!native_pet_scene->OwnedActorCount() && !native_pet_scene->AnimationBound(),
                  "scene pet releases actor and animation before effects and world");
            native_pet_scene.reset();
        }
        if (native_scene_effects) native_scene_effects->StopWorldWeather();
        if (native_script_player_action) native_script_player_action->BindEquipment(nullptr);
        if (native_player_reset_effects) native_player_reset_effects->BindEquipment(nullptr);
        if (native_player_equipment_scene) {
            native_player_equipment_scene->Clear();
            Check(native_player_equipment_scene->OwnedCount()==0u,"scene releases every owned weapon before effects and world");
            native_player_equipment_scene.reset();
        }
        if (!native_scene_effects) return;
        native_scene_effects->Clear();
        native_scene_effects->BindActors(nullptr);
    }
    void VerifyNativePlayerSceneRelease() {
        EnsureNativeSceneEffects();
        LeaveNativeScenePlayers();
        auto& players=native_player_session->State();
        auto& movement=native_arena_scene_stage->Movement();
        std::array<std::uint32_t,4> clumps{}, modes{}, animations{};
        const auto actor_count=native_player_actors->Count();
        Check(actor_count==4u,"player release probe owns four original actor models");
        for (unsigned index=0;index<4u;++index) {
            auto& player=players.slots[index].base;
            clumps[index]=player.Read(0x14u); modes[index]=player.Read(0x18u);
            animations[index]=player.Read(0x17cu);
            Check(clumps[index] && !RpClumpGetWorld(reinterpret_cast<RpClump*>(clumps[index])),
                  "player release fixture starts with detached original models");
            player.Write(0x18u,index<2u?0u:1u);
            (void)pal4::BaseObjectActivity::SetStateFlag(player,1u);
            Check(pal4::NativeArenaCharacterCollisionBinding::Initialize(player,
                      native_arena_scene_stage->CollisionTree())!=0u,
                  "player release fixture binds each actual collision actor");
            if(index<3u) Check(pal4::NativeArenaWorldClumpBinding::Attach(
                      native_arena_manager->Address(),reinterpret_cast<RpClump*>(clumps[index])),
                  "player release fixture attaches standalone and externally owned models");
            (void)pal4::NativeRwGeometryProcessor::ProcessClump(
                reinterpret_cast<RpClump*>(clumps[index]),native_arena_manager->Address()+300u);
            const auto handle=native_scene_effects->GobEffects().Create("foot_2",0xffffffffu,false);
            Check(handle.second!=0u && !player.Read(0x524u),"player release fixture owns a fresh hand effect");
            player.Write(0x520u,handle.first); player.Write(0x524u,handle.second);
        }
        const auto registered_before=movement.RegisteredObjectAtomics();
        Check(movement.RegisterObjectClump(reinterpret_cast<RpClump*>(clumps[1]),0u),
              "player release fixture has actual movement registrations");
        players.Word((0xb14u+0xb10u)/4u)=1u;
        const auto pending=native_scene_effects->PendingCount();
        LeaveNativeScenePlayers();
        Check(native_scene_effects->PendingCount()==pending+4u &&
                  native_player_actors->Count()==actor_count &&
                  movement.RegisteredObjectAtomics()==registered_before &&
                  !players.Word((0xb14u+0xb10u)/4u),
              "four-player leave retires hand effects and movement while retaining loaded actor owners");
        for(unsigned index=0;index<4u;++index) {
            auto& player=players.slots[index].base;
            Check(!player.Read(0x1f0u) && !player.Read(0x568u) && !player.Read(0x524u) &&
                      player.Read(0x14u)==clumps[index] && player.Read(0x17cu)==animations[index] &&
                      RpClumpGetWorld(reinterpret_cast<RpClump*>(clumps[index]))==
                          (index==2u?native_arena_world.World():nullptr),
                  "all four slots leave with exact mode-dependent membership and preserved clumps/animation");
        }
        LeaveNativeScenePlayers();
        Check(native_scene_effects->PendingCount()==pending+4u,
              "repeat player leave does not retire effects twice");
        Check(pal4::NativeArenaWorldClumpBinding::Detach(native_arena_manager->Address(),
                  reinterpret_cast<RpClump*>(clumps[2])),"external owner releases preserved mode1 world fixture");
        for(unsigned index=0;index<4u;++index) players.slots[index].base.Write(0x18u,modes[index]);
        std::cout << "Native player scene release: four original models, hand effects, collision/movement, world modes, retained animation and repeat cleanup verified\n";
    }
    void VerifyNativePetSceneRelease() {
        EnsureNativeSceneEffects();
        Check(native_pet_scene && !native_pet_scene->OwnedActorCount(),
              "pet scene probe has empty actual persistent owner");
        auto& pet = native_pet->Base();
        const auto allocations = native_pet_memory.OutstandingAllocations();
        native_pet_scene->LoadActor();
        native_pet->InitializeData(reinterpret_cast<std::uint32_t>(
            &native_player_session->State().slots[0u].base));
        (void)pal4::BaseObjectActivity::SetStateFlag(pet, 1u);
        Check(native_pet_scene->OwnedActorCount() == 1u && native_pet_scene->AnimationBound() &&
                  pet.Read(0x18u) == 1u && native_pet_scene->Enter() == 1u &&
                  pet.Read(0x568u) == native_arena_scene_stage->CollisionTree().TreeAddress(),
              "original339 pet loads real clumps, clips and scene collision binding");
        const auto clump = reinterpret_cast<RpClump*>(pet.Read(0x14u));
        const auto handle = native_scene_effects->GobEffects().Create("foot_2", 0xffffffffu, false);
        Check(handle.second != 0u, "pet release probe owns an original hand Dialog");
        pet.Write(0x520u, handle.first); pet.Write(0x524u, handle.second);
        const auto pending = native_scene_effects->PendingCount();
        Check(native_pet_scene->Remove() == 1u && !pet.Read(0x1f0u) && !pet.Read(0x568u) &&
                  !pet.Read(0x524u) && native_scene_effects->PendingCount() == pending + 1u &&
                  pet.Read(0x14u) == reinterpret_cast<std::uint32_t>(clump),
              "pet script removal retires actual hand effect and collision before model reset");
        pet.Write(0x18u, 0u);
        (void)pal4::BaseObjectActivity::SetStateFlag(pet, 1u);
        Check(native_pet_scene->Enter() == 1u && RpClumpGetWorld(clump) == native_arena_world.World() &&
                  native_pet_scene->Remove() == 1u && !RpClumpGetWorld(clump),
              "standalone pet enters and leaves actual SDK world");
        (void)pal4::BaseObjectActivity::SetStateFlag(pet, 1u);
        Check(native_pet_scene->Enter() == 1u, "reenter pet before attached branch probe");
        pet.Write(0x18u, 1u);
        Check(native_pet_scene->Remove() == 1u && RpClumpGetWorld(clump) == native_arena_world.World(),
              "attached pet removal preserves its external world binding");
        Check(pal4::NativeArenaWorldClumpBinding::Detach(native_arena_manager->Address(), clump),
              "external owner retires the attached-branch world fixture");
        native_pet_scene->Clear();
        Check(!native_pet_scene->OwnedActorCount() && !native_pet_scene->AnimationBound() &&
                  !pet.Read(0x14u) && !pet.Read(0x30u) && !native_pet->Source() &&
                  native_pet_memory.OutstandingAllocations() == allocations,
              "pet virtual reset releases original actor and animation and preserves base members");
        native_pet_scene->Clear();
        Check(native_pet_memory.OutstandingAllocations() == allocations,
              "repeated pet scene clear does not free persistent members");
        pal4::NativeAngelScriptEngine engine;
        const std::string source = "void Show() { giPetShow(true); } "
                                   "void Hide() { giPetShow(false); giPetShow(false); }";
        Check(engine.Raw()->AddScriptSection("pet_probe", "pet_probe.cs",
                  source.data(), source.size()) >= 0 && engine.Raw()->Build("pet_probe") >= 0,
              "compile pet show/hide through original script signature");
        pal4::NativeGameScriptServices services{};
        services.pet_visibility = &native_pet_scene->VisibilityRuntime();
        pal4::NativeGameScriptCallbacks callbacks(services);
        engine.SetCallbacks(&callbacks);
        pal4::NativeScriptFrameRunner runner(engine);
        const auto run = [&](const char* function) {
            runner.Queue("pet_probe", function);
            Check(runner.Tick(0.0f) == pal4::NativeScriptFrameStatus::finished && runner.Error().empty(),
                  "compiled pet callback completes without script exception or suspension");
        };
        auto& leader = native_player_session->State().Word(0x2c50u / 4u);
        const auto old_leader = leader;
        const auto enabled_address = native_pet->Address() + 0x654u;
        const auto old_enabled = native_pet_memory.ReadDword(enabled_address);
        leader = 0u;
        run("Show");
        Check(native_pet_memory.ReadDword(enabled_address) == 1u && native_pet_scene->AnimationBound() &&
                  native_pet_scene->OwnedActorCount() == 1u && pet.Read(0x1f0u) == 1u &&
                  native_pet->Source() == native_player_session->Address() && pet.Read(0x18u) == 1u,
              "VM giPetShow creates actual339 from leader zero with original load mode");
        pal4::test::VerifyNativeScenePetRender(*native_pet_scene,*native_pet,*native_arena_manager,native_arena_world,[]{RestoreSceneFrameRenderStates();});
        const auto loaded_allocations = native_pet_memory.OutstandingAllocations();
        run("Show");
        Check(native_pet_scene->OwnedActorCount() == 1u &&
                  native_pet_memory.OutstandingAllocations() == loaded_allocations,
              "repeated VM show resets old pet before replacement without tracked allocation growth");
        leader = 1u;
        run("Show");
        Check(native_pet_memory.ReadDword(enabled_address) == 1u && !native_pet_scene->AnimationBound() &&
                  !native_pet_scene->OwnedActorCount() && !pet.Read(0x14u) && !native_pet->Source(),
              "nonzero leader VM show retires old model while preserving enabled flag");
        run("Hide");
        Check(!native_pet_memory.ReadDword(enabled_address) && !native_pet_scene->OwnedActorCount() &&
                  native_pet_memory.OutstandingAllocations() == allocations,
              "VM repeated hide clears enable and returns to persistent allocation baseline");
        leader = old_leader;
        native_pet_memory.WriteDword(enabled_address,old_enabled);
        std::cout << "Native pet VM: giPetShow true/false, repeated replacement, leader gate and allocation baseline verified\n";
        native_pet_scene->LoadActor();
        (void)pal4::BaseObjectActivity::SetStateFlag(pet, 1u);
        Check(native_pet_scene->Enter() == 1u && native_pet_scene->AnimationBound(),
              "same pet session reloads339 and remains loaded for real scene teardown");
        std::cout << "Native pet scene: original339, hand effect, standalone/attached world branches, "
                     "reset/reload and pending actual scene teardown verified\n";
    }
    void VerifyNativeEquipmentActions() {
        Check(native_script_player_action && native_player_animation_binding &&
                  !native_script_player_action->Waiting(),"equipment action probe requires an idle script waiter");
        EnsureNativeSceneEffects();
        Check(native_player_equipment_scene && native_player_equipment_scene->OwnedCount()==0u,
              "equipment action probe starts without a named weapon");
        auto& slot=native_player_session->State().slots[0];
        auto& player=slot.base;
        auto& animation=*reinterpret_cast<pal4::GameObjectEmbeddedAnimationState*>(
            reinterpret_cast<std::uint32_t>(&player)+0x170u);
        const auto saved=animation;
        const auto old_action=std::string(native_script_player_action->CurrentRecordName(
            reinterpret_cast<std::uint32_t>(&player)));
        const auto old_time=native_player_actors->At(0u).Hierarchy()->currentAnim->currentTime;
        const auto packages_before=native_packages->LoadedPackageCount();
        // A compiled test script reaches the registered VM callback. The real
        // scene's story context remains intact; wait=false borrows its action
        // service without suspending that context from a different runner.
        pal4::NativeAngelScriptEngine engine;
        constexpr char source[]="void Equip() { giPlayerDoAction(0, \"Z01\", 0, false); } void Unequip() { giPlayerDoAction(0, \"C01\", 0, false); }";
        Check(engine.Raw()->AddScriptSection("equipment_probe","equipment_probe.cs",source,sizeof(source)-1u)>=0 &&
                  engine.Raw()->Build("equipment_probe")>=0,"compile the equipment callback probe");
        pal4::NativeGameScriptServices services{};services.player_action=native_script_player_action.get();
        pal4::NativeGameScriptCallbacks callbacks(services);engine.SetCallbacks(&callbacks);
        pal4::NativeScriptFrameRunner runner(engine);
        for (unsigned pass=0;pass<2u;++pass) {
            runner.Queue("equipment_probe","Equip");
            Check(runner.Tick(0.0f)==pal4::NativeScriptFrameStatus::finished && runner.Error().empty(),
                  "VM giPlayerDoAction callback reaches the bound equipment service");
            Check(native_script_player_action->Waiting() && native_player_equipment_scene->OwnedCount()==1u &&
                      player.Read(0x39cu) && !player.Read(0x22cu) &&
                      RpClumpGetWorld(reinterpret_cast<RpClump*>(player.Read(0x39cu)))==native_arena_world.World() &&
                      std::string(reinterpret_cast<const char*>(player.Read(0x388u+16u)))=="WTA1",
                  "Z01 action reaches live3501 equipment and original101 left weapon in the current world");
            native_script_player_action->ClearHandlers();
            if (!pass) {
                runner.Queue("equipment_probe", "Unequip");
                Check(runner.Tick(0.0f)==pal4::NativeScriptFrameStatus::finished && runner.Error().empty(),
                      "non-equipment action callback runs the original cleanup branch");
                native_script_player_action->ClearHandlers();
                Check(!native_player_equipment_scene->OwnedCount() && !player.Read(0x39cu),
                      "script action cleanup releases actual named weapon before replacement");
            }
        }
        Check(native_player_animation_binding->Select(old_action) &&
                  native_player_animation_binding->SetTime(old_time),"equipment action probe restores the previous clip");
        animation=saved;
        Check(native_packages->LoadedPackageCount()==packages_before,
              "equipment action replacement balances nested package references");
        std::cout<<"Native application equipment: compiled VM giPlayerDoAction/Z01, original101/3501/WTA1, cleanup/replacement; live weapon retained for scene release\n";
    }
    void VerifyNativeSavedGameRestore() try {
        Check(config_path && native_player_model_reload && native_player_equipment_scene &&
                  native_pet && native_collection_runtime && native_reset_ops,
              "saved equipment restore has persistent native owners");
        if(native_active_player_scene) {
            native_active_player_scene->Release();native_active_player_scene.reset();
        }
        UnbindNativeActorSceneEvents();
        native_player_animations->Release();
        const auto allocations_before=native_player_memory.AllocationAddresses();
        const auto package_count=native_packages->LoadedPackageCount();
        pal4::NativeGameSaveArchiveReader input;
        unsigned pass{};
        for(const auto save_slot:{0,74,0}) {
            // Inventory replacement invalidates snapshot pointers. Retire
            // current weapons while their resources and scene are alive.
            native_player_equipment_scene->Clear();
            input.Close();
            pal4::GameSaveHeader header{};
            Check(input.OpenSlot(config_path->parent_path(),save_slot) &&
                      input.ReadMarker().has_value() && input.ReadHeader(header),
                  "original save prefix reads continuously from byte zero");
            pal4::NativeGameDataPersistenceRuntime data(*native_game_texture_storage,
                native_settings->State(),input,native_pet->Image());
            Check(data.Deserialize(),"original GameData restores through persistent game/global/pet owners");
            pal4::NativeInventoryLoadRuntime inventory(native_inventory,input);
            Check(inventory.Deserialize()!=0u,"original inventory restores equipment snapshots");
            Check(pal4::NativePlayerManagerLoadRuntime::Deserialize(native_player_session->State(),
                      native_player_memory,native_player_session->CopyRuntime(),input,
                      {*native_reset_ops,*native_collection_runtime,native_script_refresh,
                       *native_player_model_reload,native_player_transforms}),
                  "original four-player archive uses actual collection/skill/model services");
            const std::array<std::vector<unsigned>,4> late_passives{{
                {7069u,7029u,7400u},{7067u,7032u},{7067u,7029u},{7029u}}};
            for(unsigned index=0;index<4u;++index) {
                auto& slot=native_player_session->State().slots[index];
                const auto object=reinterpret_cast<std::uint32_t>(&slot);
                const auto script=object+pal4::PlayerManagerSlot::kScriptOffset;
                std::vector<unsigned> passives;
                for(auto entry=native_player_memory.ReadDword(script+696u);
                    entry!=native_player_memory.ReadDword(script+700u);entry+=8u) {
                    const auto record=native_player_memory.ReadDword(entry);
                    if(!record) continue;
                    Check(native_skill_catalog->ResolveRecord(record)==record,
                          "restored passive references the actual native Skill catalog");
                    passives.push_back(native_player_memory.ReadDword(record));
                }
                Check(passives==(save_slot==74?late_passives[index]:std::vector<unsigned>{}),
                      "consecutive actual player loads restore and remove the original passive roots in order");
                auto& binding=native_player_animations->For(slot.base);
                if(!binding.Bound()) binding.BindModel(reinterpret_cast<const char*>(slot.base.Read(0xcu)));
                Check(binding.Select("C01"),"saved role retains actual playable animation clips");
                native_player_equipment_scene->Apply(slot);
                const auto sequence=native_player_memory.ReadDword(object+0x920u);
                const auto item=native_inventory.FindInventoryEntry(native_inventory.Address()+0x7cu,sequence,7u);
                if(!item) {
                    Check(!slot.base.Read(0x22cu) && !slot.base.Read(0x39cu),
                          "unarmed saved role retains no named weapon clump");
                    std::cout<<"Native saved equipment: save="<<save_slot<<" player="<<index
                        <<" sequence="<<sequence<<" unarmed\n";
                    continue;
                }
                const auto text=[&](unsigned field) {
                    const auto pointer=native_inventory.ReadDword(item+field);
                    return pointer?std::string(reinterpret_cast<const char*>(pointer)):std::string{};
                };
                Check(slot.base.Read(0x22cu) || slot.base.Read(0x39cu),
                      "restored weapon snapshot creates an actual named clump");
                const auto resource=slot.base.Read(0x39cu)?0x388u:0x218u;
                const auto expected_model=index==1u && native_inventory.ReadDword(item+288u)
                    ?text(284u):text(220u);
                Check(std::string(reinterpret_cast<const char*>(slot.base.Read(resource+0xcu)))==expected_model,
                      "restored weapon model matches the saved snapshot");
                if(slot.base.Read(0x39cu) && !text(236u).empty()) {
                    const auto texture=text(236u);
                    Check(std::string(reinterpret_cast<const char*>(slot.base.Read(0x398u)))==texture,
                          "restored alternate texture metadata matches the saved snapshot");
                    struct TextureCheck {const std::string& name;unsigned materials{};bool valid{true};} result{texture};
                    (void)RpClumpForAllAtomics(reinterpret_cast<RpClump*>(slot.base.Read(0x39cu)),
                        [](RpAtomic* atomic,void* data)->RpAtomic* {
                            if(auto* geometry=RpAtomicGetGeometry(atomic))
                                (void)RpGeometryForAllMaterials(geometry,[](RpMaterial* material,void* context)->RpMaterial* {
                                    auto& check=*static_cast<TextureCheck*>(context);++check.materials;
                                    const auto* current=RpMaterialGetTexture(material);
                                    check.valid &= current && check.name==RwTextureGetName(current);
                                    return material;
                                },data);
                            return atomic;
                        },&result);
                    Check(result.materials && result.valid,"restored weapon materials reference the saved alternate texture");
                }
                for(const auto hand:{0x22cu,0x39cu}) {
                    if(!slot.base.Read(hand)) continue;
                    const auto effect=hand==0x22cu?0x4f8u:0x508u;
                    if(!text(204u).empty()) Check(slot.base.Read(effect+4u)!=0u,"saved first HEF has a live native owner");
                    if(!text(252u).empty()) Check(slot.base.Read(effect+12u)!=0u,"saved second HEF has a live native owner");
                }
                std::cout<<"Native saved equipment: save="<<save_slot<<" player="<<index
                    <<" sequence="<<sequence<<" database="<<native_inventory.ReadDword(item+144u)
                    <<" model="<<text(220u)<<" texture="<<text(236u)
                    <<" HEF0="<<text(204u)<<" HEF1="<<text(252u)<<'\n';
            }
            native_scene_effects->Update(0.05);
            native_player_equipment_scene->Clear();
            Check(!native_player_equipment_scene->OwnedCount() &&
                      native_packages->LoadedPackageCount()==package_count,
                  "consecutive saved equipment restoration balances weapon and package ownership");
            Check(native_arena_cache->LoadSection(input),
                  "original cache follows actual GameData/inventory/players restoration");
            if (++pass != 3u)
                Check(input.ReadMarker()=="ARENA_SERIALIZE_FLAG",
                      "original save cursor reaches ARENA after the persistent prefix");
        }
        native_player_animations->Release();
        const auto allocations_after=native_player_memory.AllocationAddresses();
        native_saved_player_allocation_delta=static_cast<std::ptrdiff_t>(allocations_after.size())-
            static_cast<std::ptrdiff_t>(allocations_before.size());
        for(const auto allocation:allocations_after) {
            if(std::binary_search(allocations_before.begin(),allocations_before.end(),allocation)) continue;
            bool referenced{};
            for(unsigned index=0;index<4u;++index) {
                const auto object=reinterpret_cast<std::uint32_t>(&native_player_session->State().slots[index]);
                // Script-skill, forbidden-skill and eleven HostServer array
                // begin fields are the persistent buffers touched by input.
                std::vector<unsigned> owned_fields{0x90cu,0x9ecu};
                for(unsigned array=0;array<11u;++array) owned_fields.push_back(0x93cu+array*16u);
                for(const auto offset:owned_fields)
                    if(native_player_memory.ReadDword(object+offset)==allocation) {
                        referenced=true;
                        std::cout<<"Saved player retained allocation="<<allocation<<" player="<<index
                            <<" offset="<<offset<<'\n';
                    }
            }
            Check(referenced,"restored player memory retains explicit slot ownership after all animation bindings release");
        }
        native_player_animation_binding->BindModel("101");
        std::cout<<"Native saved equipment: original0->74->0, actual four-role models/animations/inventory visuals, native passives and archive boundary verified; retained allocation delta="
            <<native_saved_player_allocation_delta<<'\n';
        Check(pal4::NativeArenaConfigLoadRuntime::Deserialize(
                  native_arena_manager->Address(), native_player_memory, input, *this),
              "continuous original save restores actual ARENA resources, objects and player scene");
        Check(native_camera_manager->LoadConfig(input),
              "continuous original save restores CAM_MGR into the replacement scene");
        BindNativeLoadedSceneServices();
        Check(pal4::NativeActorControlConfigSceneLoad::Deserialize(
                  *native_actor_session, *native_camera_manager, *native_minimap_manager,
                  *native_scene_player_movement, *native_floor_attribute,
                  native_silent_camera_listener, *this, input) != 0u && input.Remaining()==0u,
              "continuous original save restores actual actor control through exact EOF");
        // Loading prepares the initializer; the restored camera/controller must
        // be installed before its normal SDK source steps execute (IDA51A820).
        CompleteNonblockingSceneInitProbe();
        Check(native_arena_manager->LoadedWorldName()=="Q01" &&
                  native_arena_manager->LoadedAreaName()=="Q01" &&
                  native_arena_manager->SceneName()=="Q01" &&
                  native_active_player_scene && native_active_player_scene->Entered() &&
                  native_actor_session->State().words[1u]==reinterpret_cast<std::uint32_t>(
                      &native_player_session->State().slots[0].base) &&
                  native_player_memory.ReadDword(native_arena_manager->Address()+196u)==1u &&
                  native_player_memory.ReadDword(native_arena_manager->Address()+444u)==0u,
              "original save0 replaces N01 with Q01 and finishes arena/player ownership");
        std::cout << "Native saved scene: actual ARENA/CAM_MGR/actor control restored through EOF, scene="
                  << native_arena_manager->SceneName() << '\n';
        PlayMusic("wa10.wav",0u);
        const auto sound=native_ui_sound_playback->Handle();
        Check(sound && native_hud_sounds->IsPlaying(sound),
              "save UI sound helper starts original wa10 through Miles");
        PlayMusic("wa10.wav",1u);
        Check(native_ui_sound_playback->Handle()==sound,
              "shared UI sound helper suppresses overlapping flagged playback");
        PlayMusic("wa10.wav",0u);
        Check(native_ui_sound_playback->Handle()!=sound,
              "shared UI sound helper permits unflagged playback while active");
        LoadSave(0u);
        CompleteNonblockingSceneInitProbe();
        Check(native_arena_manager->LoadedAreaName()=="Q01" &&
                  native_arena_manager->ReadyFlag()==1u &&
                  native_active_player_scene && native_active_player_scene->Entered() &&
                  native_script_player_walk && native_script_player_turn && native_script_camera &&
                  native_script_system_ui && native_player_equipment_scene &&
                  native_script_session->Status()==pal4::NativeScriptFrameStatus::idle &&
                  native_script_session->EventStatus()==pal4::NativeScriptFrameStatus::idle,
              "application LoadSave repeats full original save with current scene services rebound");
        const auto* scene_before=native_second_scene_npcs.get();
        const auto* player_before=native_active_player_scene.get();
        pal4::GameSaveHeader quick_header{};
        Check(pal4::NativeGameSaveLoad::LoadSlot(config_path->parent_path(),0,true,
                  &quick_header,nullptr,NativeSaveLoadServices())!=0u && quick_header.version==1u &&
                  native_second_scene_npcs.get()==scene_before &&
                  native_active_player_scene.get()==player_before && player_before->Entered(),
              "quick original header load preserves current scene and active player owners");
        Check(!std::filesystem::exists(config_path->parent_path()/"save/99999.dat") &&
                  pal4::NativeGameSaveLoad::LoadSlot(config_path->parent_path(),99999,false,
                      nullptr,nullptr,NativeSaveLoadServices())==0u &&
                  native_second_scene_npcs.get()==scene_before &&
                  native_active_player_scene.get()==player_before && player_before->Entered(),
              "missing save performs script cleanup without destroying the current scene");
        std::cout << "Native application LoadSave: shared GameSaveReader sequence, actual wa10 guard, persistent input, repeated ARENA/camera/controller and idle scene services verified\n";
    } catch (const std::exception& error) {
        std::cerr << "Native saved scene restore: " << error.what() << std::endl;
        throw;
    }
    std::array<std::uint32_t,6> native_model_probe_constructed_text{};
    void VerifyNativePlayerModelReload() {
        Check(native_player_model_reload && native_player_equipment_scene &&
                  native_player_animation_binding && native_player_animation_binding->Bound() &&
                  !native_script_player_action->Waiting(),"loaded player reload has stable application services");
        // Save loading releases scene bindings before replacing actors. Exercise
        // the same boundary here, after cancelling script waits at shutdown.
        if(native_active_player_scene) {
            native_active_player_scene->Release();native_active_player_scene.reset();
        }
        UnbindNativeActorSceneEvents();
        auto& slot=native_player_session->State().slots[0];auto& player=slot.base;
        const auto object=reinterpret_cast<std::uint32_t>(&slot);
        const auto requested=object+0xa1cu;
        const auto old_requested=native_player_memory.ReadDword(requested);
        const auto package_count=native_packages->LoadedPackageCount();
        std::array<std::uint32_t,6> constructed_text{};
        for(unsigned i=0;i<3u;++i) {
            constructed_text[i]=player.Read(0x544u+i*4u);
            constructed_text[i+3u]=player.Read(0x554u+i*4u);
        }
        native_model_probe_constructed_text=constructed_text;
        std::array<std::uint32_t,6> transforms{};
        for(unsigned i=0;i<transforms.size();++i) transforms[i]=player.Read(0xa0u+i*4u);
        constexpr char replacement[]="103",original[]="101";
        for(const auto* model:{replacement,original}) {
            native_player_equipment_scene->Apply(slot);
            Check(native_player_equipment_scene->OwnedCount()==1u && player.Read(0x39cu),
                  "application model replacement starts with an actual equipped weapon");
            native_player_memory.WriteDword(requested,reinterpret_cast<std::uint32_t>(model));
            (void)pal4::ScriptProcessAndCleanup::Process(object,*native_player_model_reload);
            Check(!native_player_equipment_scene->OwnedCount() && !player.Read(0x39cu) &&
                      std::string(reinterpret_cast<const char*>(player.Read(0xcu)))==model &&
                      native_player_animation_binding==&native_player_animations->For(player) &&
                      native_player_animation_binding->Bound() && native_player_animation_binding->Select("C01") &&
                      player.Read(0x14u)==reinterpret_cast<std::uint32_t>(native_player_actors->At(0u).Main()) &&
                      player.Read(0x550u)==reinterpret_cast<std::uint32_t>(native_player_actors->At(0u).FaceMaterial()) &&
                      native_packages->LoadedPackageCount()==package_count,
                  "application reload retires weapons, reuses animation owner and binds actual replacement resources");
            for(unsigned i=0;i<transforms.size();++i)
                Check(player.Read(0xa0u+i*4u)==transforms[i],"application actor reload preserves position and rotation");
            native_scene_effects->Update(0.05);
        }
        native_player_memory.WriteDword(requested,old_requested);
        // Models changed inside the same arena: rebind scriptOnAdd/collision
        // ownership without adding a second LeadingRole minimap icon.
        native_active_player_scene=std::make_unique<pal4::NativeArenaActivePlayerSceneBinding>(
            player,native_arena_manager->Address(),native_arena_scene_stage->CollisionTree());
        native_active_player_scene->Enter();BindNativeLoadedSceneServices();
        Check(native_ui.RefreshSceneHudPlayers(native_player_session->State(),*native_script_player_actions),
            "model reload reentry refreshes actual HUD player controls");
        native_hud_started=true;
        Check(SceneUiEvents().ShowSceneUi(1u)==1u && native_hud_visible,
            "model reload reentry restores actual Scene HUD");
        BindNativeActorSceneEvents();
        std::cout<<"Native application model reload: actual101->103->101, equipped weapon cleanup, stable animation binding, FACE/position/rotation/package balance and playable scene reentry verified\n";
    }
    void VerifyNativePlayerSlotRetirement() {
        if(native_active_player_scene){native_active_player_scene->Release();native_active_player_scene.reset();}
        UnbindNativeActorSceneEvents();
        auto& player=native_player_session->State().slots[0].base;
        const auto object=reinterpret_cast<std::uint32_t>(&player);
        const auto& constructed_text=native_model_probe_constructed_text;
        native_player_session->SlotBaseRuntime().BaseReset(object);
        native_player_session->SlotBaseRuntime().BaseReset(object);
        for(unsigned i=0;i<3u;++i)
            Check(player.Read(0x544u+i*4u)==constructed_text[i] &&
                      player.Read(0x554u+i*4u)==constructed_text[i+3u],
                  "final slot reset retains constructed FACE/LEG text ownership");
        Check(!native_player_animation_binding->Bound() && !player.Read(0x14u) && !player.Read(0x30u) &&
                  !player.Read(0x550u) && !player.Read(0x560u),
              "final stable slot reset releases loaded actor and supports repeated reset");
        std::cout<<"Native final slot retirement: repeated reset and constructed text ownership verified\n";
    }
    pal4::NativeMilesSound2dRuntime& EnsureNativeScriptSound() {
        if (!native_sound_2d) {
            Check(config_path && native_miles_driver && native_settings,
                  "script sound preparation requires game audio and settings owners");
            auto sound = std::make_unique<pal4::NativeMilesSound2dRuntime>(
                config_path->parent_path(), *native_miles_driver,
                [](std::uint32_t source) -> std::string_view {
                    if (!source) return {};
                    return reinterpret_cast<const asCScriptString*>(source)->buffer;
                },pal4::NativeMilesSound2dRuntime::DriverRequirement::Deferred);
            sound->SetVolume(native_settings->AudioLevel(1u));
            native_sound_2d = std::move(sound);
        }
        native_scene_gob_assets.BindMachineSound(native_hud_sounds.get());
        native_scene_gob_assets.BindPlatformActorServices([this] {
            pal4::NativeGobLocalFloatActorServices actors;
            actors.transforms = &native_player_transforms;
            actors.actor_control = [this] {
                if (!native_actor_session) throw std::logic_error("LocalFloat ActorControl unavailable");
                return native_actor_session->Address();
            };
            actors.set_position = [this](std::uint32_t actor, const std::array<float,3>& p) {
                if (!native_script_player_position) throw std::logic_error("LocalFloat player position unavailable");
                native_script_player_position->SetPosition(actor, {p[0],p[1],p[2]});
            };
            actors.update_grid = [this](std::uint32_t position, std::uint32_t rotation) {
                if (!native_minimap_manager) throw std::logic_error("LocalFloat minimap unavailable");
                native_minimap_manager->UpdateGrid(position, rotation);
            };
            actors.update_floor = [this] {
                if (!native_floor_attribute) throw std::logic_error("LocalFloat floor attributes unavailable");
                native_floor_attribute->Update(); return 0u;
            };
            return actors;
        });
        native_scene_gob_assets.BindObstacleActorServices([this] {
            pal4::NativeGobObstacleActorServices actors;
            actors.actor_control=[this]{Check(native_actor_session!=nullptr,"Obstacle ActorControl owner");return native_actor_session->Address();};
            actors.world_force=[this](const std::array<float,3>& delta){
                Check(native_actor_session && native_camera_manager && native_minimap_manager && native_script_player_action &&
                    native_scene_player_movement && native_floor_attribute && native_script_player_position,"Obstacle movement creating services");
                const auto actor=native_actor_session->State().words[1u];if(!actor)return;
                pal4::NativeActorControlDiscreteMovementRuntime movement(*native_actor_session,*native_camera_manager,
                    *native_minimap_manager,*native_script_player_action,*native_scene_player_movement,*native_floor_attribute,
                    native_player_transforms,native_player_memory,ActiveInput(),actor,*native_script_player_position);
                pal4::ActorControlMovementGlobals globals;
                (void)pal4::ActorControlWorldMovement::ApplyDelta(actor,reinterpret_cast<std::uint32_t>(delta.data()),globals,movement);
            };
            actors.floor_sound=[this](float elapsed){NativeActorHazards().TickFloorSound(elapsed);};
            actors.apply_status=[this](float value){NativeActorHazards().ApplyStatus(value);};
            actors.start_status=[this](std::uint32_t duration,std::uint32_t interval,float value){NativeActorHazards().StartStatus(duration,interval,value);};
            actors.movement_status=[this](std::uint32_t duration){NativeActorHazards().BeginMovement(duration);};
            actors.script_path=[this]{Check(native_arena_manager!=nullptr,"Obstacle scene script owner");return std::string(native_arena_manager->SceneScriptPath());};
            return actors;
        });
        native_scene_gob_assets.BindSoundServices([this] {
            return pal4::NativeGobSoundServices{native_camera_manager.get(),[this]() -> pal4::NativeMilesSound3dRuntime& {return Native3dSounds();}};
        });
        native_scene_gob_assets.BindMachineServices([this] {
            pal4::NativeGobMachineServices machine;
            machine.arena=native_arena_manager->LoadedWorldName();
            machine.scene=native_arena_manager->SceneName();
            machine.cameras=native_camera_manager.get();
            machine.effects=native_scene_effects.get();
            machine.objects=native_script_object_visibility.get();
            machine.reward.inventory=&native_inventory;
            machine.reward.database=&native_database;
            machine.reward.hints=native_inventory_change.get();
            machine.reward.hint_visible=[this]{return native_ui.HintVisible();};
            machine.game_event=[this](std::uint32_t key){native_settings->RecordEventKey(key);};
            machine.script=NativeArenaScriptScope();
            machine.refresh_minimap=[this]{native_minimap_manager->RefreshObjectSprites(native_scene_gob_assets);};
            machine.queue_fade_out=[this](std::uint32_t address){
                auto* object=native_scene_gob_assets.FindMutableObjectByAddress(address);
                if(!object)throw std::invalid_argument("Machine scene registration object");
                (void)native_arena_manager->AddActiveSceneObject(address,1.0f);
            };
            return machine;
        });
        return *native_sound_2d;
    }
    // Compose borrowed services at the execution boundary; scene release may
    // have retired some adapters since the preceding NewGame or scene script.
