            native_npc_blend=std::make_unique<pal4::NativeScriptNpcBlendRuntime>(
                *CurrentSceneNpcs(),native_arena_manager->Address(),native_script_session->Context());
        services.npc_blend=native_npc_blend.get();
        if(native_npc_blend && native_script_player_actions)
            native_npc_blend->BindPlayers(*native_script_player_actions);
