        if(native_opening_wait)native_opening_wait->BindSceneCommonDialog(*native_common_script_wait);
        if(native_opening_wait)native_opening_wait->BindSceneSelectDialog(*native_select_script_wait);
        if(native_opening_wait)native_opening_wait->BindScenePuzzle(*native_puzzle_script_wait);
        if(native_opening_wait)native_opening_wait->BindSceneTrade(*native_trade_script_wait);
