    std::uint32_t AcquireNativeCombatSystem() {
        if(!native_combat_access)throw std::logic_error("PAL4 Combat native constructor dependencies are not composed");
        const auto before=native_combat_access->RegistrationCount();
        const auto instance=native_combat_access->Acquire();
        if(!before)std::cout<<"Native combat acquisition: cbCombatSystem id1028 registered=1 cold517="
                           <<static_cast<unsigned>(native_combat_memory.ReadByte(instance+517u))<<'\n';
        return instance;
    }
    pal4::ActorEffectHandle CreateCombatActorEffect(std::uint32_t actor,std::string_view resource,std::string_view mode){
            for(auto& model:native_combat_player_models)if(model->ActorAddress()==actor){
                pal4::NativeCombatActorEffects factory(*model,*native_scene_effects,native_combat_events);return factory.Create(resource,mode);
            }
            if(native_combat_monsters)for(std::size_t i=0;i<native_combat_monsters->Count();++i)if(native_combat_monsters->ActorAt(i)==actor){
                pal4::NativeCombatActorEffects factory(native_combat_monsters->ModelOwner(actor),*native_scene_effects,native_combat_events);return factory.Create(resource,mode);
            }
            throw std::invalid_argument("Combat Skill effect actor model is not bound");
    }
    void BindCombatSkillEffects(std::uint32_t actor,pal4::NativeCombatActorSkillRuntime& skills){
        pal4::NativeCombatSkillEffectServices effects;
        effects.create=[this,actor](std::string_view resource,std::string_view mode){return CreateCombatActorEffect(actor,resource,mode);};
        effects.active=[this](pal4::ActorEffectHandle h){return pal4::EffectHandle::DialogNeedsUpdate({h.id,h.owner},native_scene_effects->ContentHandles());};
        effects.release=[this](pal4::ActorEffectHandle h){pal4::EffectSystemHandleWords words{h.id,h.owner};pal4::EffectHandle::Release(words,false,native_scene_effects->ContentHandles());};
        skills.BindEffectServices(std::move(effects));
        skills.BindRelatedTargets([this](auto actor){
            Check(native_combat_target_actors!=nullptr,"actual9100 roster target owner");
            return native_combat_target_actors->CollectRelated(actor);
        });
        skills.BindAllTargets([this](auto actor){
            Check(native_combat_target_actors!=nullptr,"actual9115 full roster target owner");
            return native_combat_target_actors->CollectAll(actor);
        });
        skills.BindConditionalRetirement([this,actor,&skills]{
            Check(native_scene_effects!=nullptr,"actual9126 retirement effects");
            if(!skills.IsPlayerActor()){
                Check(native_combat_monsters!=nullptr,"actual9126 Monster manager");
                (void)native_combat_monsters->RetireActorDuringSkill(actor,*native_scene_effects);return;
            }
            for(auto& cache:native_combat_player_models)if(cache->ActorAddress()==actor){
                (void)pal4::RetireNativeCombatActorDuringSkill(native_combat_players->Actor(actor),skills,
                    native_scene_effects->ContentHandles(),[&]{(void)cache->LeaveStageDuringSkill(native_combat_events,skills);});return;
            }
            throw std::logic_error("Combat9126 Player model cache is not bound");
        });
        skills.BindDamageActions([this](auto callback,auto record,auto source,auto target){
            Check(native_combat_damage_calculator && native_combat_target_actors,"actual Skill damage dependencies");
            native_combat_damage_calculator->ApplyAction(callback,record,source,target,
                [this](auto actor){return native_combat_target_actors->CollectRelated(actor);});
        });

    }
    void BindCombatActorTurn(std::uint32_t actor,pal4::NativeCombatPlayerModelCache* player=nullptr) {
        const auto geometry=[this]{return native_combat_world->GeometryQueue();};
        std::unique_ptr<pal4::NativeCombatActorTurnRuntime> turn;
        std::unique_ptr<pal4::NativeCombatDeathDomain> domain;
        if(player) {
            pal4::NativeCombatActorSkillRuntime* skills=nullptr;
            for(auto& owner:native_combat_player_skills)if(owner->ActorAddress()==actor)skills=owner.get();
            Check(skills && player->ActorAddress()==actor,"new Player turn uses matching real cache/skills");
            turn=std::make_unique<pal4::NativeCombatActorTurnRuntime>(*player,native_combat_image,geometry);
            domain=std::make_unique<pal4::NativeCombatDeathDomain>(*player,*skills,*turn,native_combat_image,
                *native_skill_system,*native_collection_catalog,native_combat_events);
        } else {
            auto& model=native_combat_monsters->ModelOwner(actor);
            auto& skills=native_combat_monsters->Skills(actor);
            turn=std::make_unique<pal4::NativeCombatActorTurnRuntime>(model,geometry,[this](auto a){
                native_combat_monsters->ApplyPendingSceneRecord(a,*native_collection_catalog,*native_scene_effects);
            });
            domain=std::make_unique<pal4::NativeCombatDeathDomain>(model,skills,*turn,native_combat_image,
                *native_skill_system,*native_collection_catalog,*native_scene_effects);
        }
        const auto count=native_combat_turns.size()+1u;
        native_combat_turns.reserve(count);native_combat_turn_actors.reserve(count);native_combat_death_domains.reserve(count);
        auto& actions=domain->Actions();
        Check(native_combat_task_queue!=nullptr,"Combat task queue exists before actor creation");
        native_combat_task_queue->BindActions(actions);
        turn->BindDeathQueue(actions,*native_combat_task_queue);
        native_combat_turn_actors.push_back(actor);native_combat_turns.push_back(std::move(turn));
        native_combat_death_domains.push_back(std::move(domain));
    }
    void BindCombatReactionDomains() {
        Check(native_combat_task_queue && native_combat_turn_actors.size()==native_combat_death_domains.size(),
              "reaction domains follow actual turn/death ownership");
        native_combat_reaction_domains.reserve(native_combat_turn_actors.size());
        auto& scale=*reinterpret_cast<float*>(game.Address()+1404u);
        for(std::size_t i=0;i<native_combat_turn_actors.size();++i){
            const auto actor=native_combat_turn_actors[i];
            bool bound=false;for(auto& old:native_combat_reaction_domains)if(old->ActorAddress()==actor)bound=true;
            if(bound)continue;
            auto& deaths=native_combat_death_domains[i]->Actions();
            std::unique_ptr<pal4::NativeCombatReactionDomain> reactions;
            pal4::NativeCombatPlayerModelCache* player=nullptr;
            for(auto& model:native_combat_player_models)if(model->ActorAddress()==actor)player=model.get();
            if(player){
                pal4::NativeCombatActorSkillRuntime* skills=nullptr;
                for(auto& skill:native_combat_player_skills)if(skill->ActorAddress()==actor)skills=skill.get();
                // Reserve Players retain lazy reaction owners without a model.
                // Current() is resolved only when an actual action needs it.
                Check(skills && player->ActorAddress()==actor,"Player reactions retain matching actor/skill owners");
                reactions=std::make_unique<pal4::NativeCombatReactionDomain>(*player,*skills,*native_combat_skill_registry,
                    native_combat_image,*native_skill_system,*native_scene_effects,native_combat_events,scale,deaths,
                    [this](std::uint32_t a,std::uint32_t flag){native_combat_player_motion->Update(a,flag);});
            }else{
                reactions=std::make_unique<pal4::NativeCombatReactionDomain>(native_combat_monsters->ModelOwner(actor),
                    native_combat_monsters->Skills(actor),*native_combat_skill_registry,native_combat_image,
                    *native_skill_system,*native_scene_effects,native_combat_events,scale,deaths,
                    [this](std::uint32_t a,std::uint32_t flag){native_combat_monsters->UpdateMonsterMotion(a,flag);});
            }
            reactions->BindWounded(*native_combat_end_sound_events);
            if(!player)reactions->BindFinalHit(native_combat_monsters->ModelOwner(actor),*native_scene_effects,native_combat_events);
            const std::array<pal4::INativeCombatTaskDomain*,3> owners{&reactions->FendOff(),&reactions->Miss(),&reactions->Wounded()};
            native_combat_task_queue->BindActions(owners);
            native_combat_reaction_domains.push_back(std::move(reactions));
        }
    }
    pal4::NativeCombatEventActor ResolveCombatEffectActor(std::uint32_t actor) {
        for(auto& cache:native_combat_player_models)if(cache->ActorAddress()==actor){
            const auto child=cache->Current().Address();
            if(!child)throw std::logic_error("ActorManager Player model unavailable");
            return {1u,child+172u,child+160u,*reinterpret_cast<const std::uint32_t*>(actor+1192u)};
        }
        if(native_combat_monsters)for(std::size_t i=0;i<native_combat_monsters->Count();++i)
            if(native_combat_monsters->ActorAt(i)==actor){
                const auto* child=native_combat_monsters->ModelOwner(actor).Model();
                if(!child)throw std::logic_error("ActorManager Monster model unavailable");
                return {2u,child->Address()+172u,child->Address()+160u,std::nullopt};
            }
        throw std::invalid_argument("foreign production ActorManager actor");
    }
    void BindNativeCombatFacetReader() {
        native_scene_effects->BindDialogFacetReader([this](std::uint32_t facet){
            if(facet<724u)throw std::invalid_argument("foreign production Combat position facet");
            const auto view=ResolveCombatEffectActor(facet-724u);
            std::array<float,3> position{};
            std::memcpy(position.data(),reinterpret_cast<const void*>(view.position),sizeof(position));
            return position;
        });
    }
