    ~Services() {
        StopPersistentWorldMap();
        native_puzzle.reset();
        ReleaseNativeMonsterUpdates();
        StopPersistentSystemMenu();
        native_combat_config.Unbind();native_combat_config_bound=false;
        if(native_game_over && native_game_over->Entered())native_game_over->Leave();
        if(native_logo_lifecycle && native_logo_lifecycle->Entered())(void)native_logo_lifecycle->Leave();
        RetirePreparedCombatActors(true);
        native_combat_game_events.reset();
        native_combat_console.reset();
        if(native_combat_skill_registry) {
            Check(native_combat_skill_registry->Count()==0u,"native Monster routing registry retires actors");
            native_combat_skill_registry.reset();
        }
        native_combat_monster_records.reset();
        native_combat_formulas.reset();
        // Archive failures may occur before the normal scene-release tail.
        // Reuse the same owner teardown while its dependencies remain alive.
        if((native_second_scene_npcs || native_opening_scene_npcs) &&
            native_arena_scene_stage && native_arena_world.World())
            ReleaseCurrentScene();
        if (native_pet_scene) {
            native_pet_scene->Clear();
            native_pet_scene.reset();
        }
        ReleaseNativeFloorServices();
        if(native_arena_scene_stage) {
            native_arena_scene_stage->Release();
            native_arena_scene_stage.reset();
        }
        native_monster_manager.reset();
        native_second_scene_npcs.reset();
        native_opening_scene_npcs.reset();
        RetireCombatManagerGroup();
        // Registered callbacks borrow members of Services. Retire them while all
        // state owners and backing PALGameIV bytes still exist, also on failure.
        if (native_state_list) native_state_list->Clear();
        native_combat_state.reset();
        native_game_over.reset();
        // Countdown borrows the timer queue; retire it before automatic member teardown.
        native_scene_frames.ReleaseActorFrame();
        native_minimap_scene_ui.reset();
        // The texture owner removes its timer and reads the backing game image.
        native_game_texture_storage.reset();
        if (allocation != nullptr) {
            config.UnbindExternal();
            game.UnbindExternal();
        }
    }
#endif

