                    auto& result=*static_cast<WorldFiltering*>(context);
                    if(auto* texture=RpMaterialGetTexture(material)){
                        ++result.textured;
                        if(RwTextureGetFilterMode(texture)!=rwFILTERLINEAR)++result.wrong;
                    }
                    return material;
