            const auto entry=native_game_texture_storage?*reinterpret_cast<const std::uint32_t*>(native_game_texture_storage->Address()+396u):0u;
            const bool available=native_state_list && entry && native_state_list->StateId(entry)==1u &&
                native_actor_session && native_actor_session->State().words[0]==1u && native_script_player_position &&
                !input_runtime.ComparisonPendingSamples();
