    void ReleaseOpeningNpcProbe() {
        if (native_scene_npc_object) {
            native_scene_npc_object->UnbindBehavior();
            native_scene_npc_object->UnbindManagerGrid();
        }
        if (native_npc_manager) {
            Check(native_scene_npc_object &&
                      native_npc_manager->FindObject("MN001") ==
                          native_scene_npc_object->Address(),
                  "NPC manager owns the live name-tree registration");
            native_npc_manager->Destroy();
            Check(native_npc_manager->OutstandingAllocations() == 0u,
                  "scene releases NPC manager trees and grid");
            native_npc_manager.reset();
            native_npc_info.reset();
        }
        if (native_scene_npc_object) {
            native_scene_npc_object->Destroy();
            Check(native_scene_npc_object->Address() == 0u &&
                      !native_scene_npc_object->ActorBound() &&
                      native_scene_npc_actor->Main() != nullptr,
                  "scene releases NPC component image before actor");
            native_scene_npc_object.reset();
        }
        if (native_scene_npc_actor) {
            native_scene_npc_actor->Unload();
            native_scene_npc_actor.reset();
        }
    }
    void ReleaseFirstSceneForSwitch() {
        Check(native_arena_load && native_arena_load->LoadingScenePending() &&
                  native_loading_scene_loaded && native_loading_reached_95 &&
                  native_arena_scene_stage && native_arena_manager && native_scene_effects &&
                  native_arena_manager->SceneName() == "N01" &&
                  native_loading_state->String(24u) == "Q01",
              "first scene release requires a pending Loading switch");
        ReleaseCurrentSceneForTransition();
        Check(native_scene_gob_assets.Size() == 0u &&
                  native_scene_gob_assets.NameTreeAddress() != 0u &&
                  native_scene_gob_assets.FactoryCount() == 11u &&
                  native_scene_gob_assets.FindRecord("MO001") == nullptr &&
                  native_scene_gob_assets.FindObject("MO001") == nullptr &&
                  native_player_memory.OutstandingAllocations() ==
                      native_scene_gob_memory_before +
                          native_player_animation_memory_retained +
                          native_scene_gob_assets.RetainedManagerAllocations(),
              "scene teardown releases GOB images, records and models");

        for (const auto& slot : native_player_session->State().slots)
            Check(slot.base.Read(0x568u) == 0u &&
                      slot.base.Read(0x56cu) == 0u,
                  "scene teardown clears borrowed player floor faces");
        Check(!native_opening_wait->BlocksScript(),
              "scene switch detaches destroyed script wait services");
    }

    void RestoreNativeLoadedSceneUi() {
        if (!native_hud_started) return;
        // BindNativeLoadedSceneServices advances the destination initializer.
        // Preserve a giLockPlayer hide issued there: IDA58F190 shows Scene UI
        // only while ActorControl is enabled, as shared WorldState::Enter does.
        if (native_actor_session->State().words[0u] != 0u && !native_hud_visible)
            Check(SceneUiEvents().ShowSceneUi(1u) == 1u && native_hud_visible,
                  "loaded scene restores HUD only with enabled ActorControl");
        BindNativeActorSceneEvents();
    }
    std::uint32_t AdvancePendingSceneLoading() {
        const bool story_switch = native_script_session->Status() ==
            pal4::NativeScriptFrameStatus::suspended;
        if (story_switch)
            ReleaseFirstSceneForSwitch();
        const auto result = story_switch
            ? AdvanceNativeLoadingWithPresentation()
            : AdvancePendingReloadedSceneLoading("Q01");
        Check((story_switch ||
               (native_script_session->Status() ==
                    pal4::NativeScriptFrameStatus::finished &&
                native_script_session->EventStatus() ==
                    pal4::NativeScriptFrameStatus::suspended)) &&
                  native_monster_manager && native_minimap_manager &&
                  native_scene_gob_assets.Size() != 0u,
              "Q01/Q01 scene resources are ready for the suspended script");
        BindNativeLoadedSceneServices(story_switch);
        RestoreNativeLoadedSceneUi();
        return result;
    }
    pal4::BaseObjectState& LeaderPlayer(std::uint32_t actor) {
        Check(native_player_session!=nullptr,"leader owns persistent Player slots");
        for(auto& slot:native_player_session->State().slots)
            if(reinterpret_cast<std::uint32_t>(&slot.base)==actor)return slot.base;
        throw std::invalid_argument("leader actor is not a persistent Player");
    }
    void SetLeaderAction(std::uint32_t actor,std::uint32_t name) override {
        (void)LeaderPlayer(actor);
        Check(name==pal4::PlayerManagerLeaderTransition::kActionName && native_script_player_action,
            "leader selects the original C01 action through actual animation services");
        Check(native_script_player_action->SetAction(actor,"C01")!=0,"leader C01 exists in actual role assets");
    }
