    void ReleaseReloadedScene(bool verify_story_fixture=false) {
        Check(native_second_scene_npcs != nullptr,"reloaded release requires its NPC creating owner");
        ReleaseCurrentScene(verify_story_fixture);
    }
    void ReleaseCurrentSceneForTransition(bool verify_story_fixture=false) {
        // IDA518A60 disables temperature, captures the outgoing scene (unless
        // archive restoration), then releases its objects. NewGame, LoadSave
        // and shutdown deliberately use ReleaseCurrentScene directly.
        Check(native_arena_cache != nullptr, "scene transition retains arena cache owner");
        native_temperature_manager->Disable(native_scene_frames);
        native_arena_cache->CaptureCurrent(CaptureNativeCurrentArena());
        ReleaseCurrentScene(verify_story_fixture);
    }
    void ReleaseCurrentScene(bool verify_story_fixture=false) {
        ReleaseNativeMonsterUpdates();
        const bool opening = !native_second_scene_npcs;
        auto* scene_npcs = opening ? native_opening_scene_npcs.get() : native_second_scene_npcs.get();
        Check(native_arena_scene_stage && native_arena_manager && native_scene_effects &&
                  scene_npcs && native_path_planner && native_camera_manager &&
                  native_monster_manager && (opening || (native_temperature_manager && native_floor_attribute)) &&
                  native_script_session && native_actor_session && native_player_session && native_pet,
              "full scene release requires current creating owners");
        const bool leaving_q01=native_arena_manager->SceneName()=="Q01";
        const auto primary=native_script_session->Status();
        const auto event=native_script_session->EventStatus();
        const auto story=native_script_session->GlobalStoryVariable();
        std::size_t allocations_before_actor_release = 0u;
        std::size_t retired_actor_allocations = 0u;
        std::size_t gob_allocations_before_clear = 0u;
        const auto detach_borrowers = [&] {
            if (native_scene_init_execution) {
                // Scene replacement retires borrowers, preserving suspended stack entries.
                native_script_session->DetachConcurrentSceneServices();
                native_scene_init_execution->ClearHandlers();
                native_scene_init_execution.reset();
            }
            if (native_script_session->Status()==pal4::NativeScriptFrameStatus::idle)
                native_script_session->BindServices({});
            else if (native_script_session->Status()==pal4::NativeScriptFrameStatus::suspended)
                native_script_session->DetachSceneServices();
            if(native_script_session->EventStatus()==pal4::NativeScriptFrameStatus::suspended)
                native_script_session->DetachEventServices();
            else if(native_script_session->EventStatus()==pal4::NativeScriptFrameStatus::queued)
                native_script_session->CancelQueuedEvent();
            else native_script_session->BindEventServices({});
            if (native_event_execution) native_event_execution->ClearHandlers();
            native_event_execution.reset();
            native_opening_wait->UnbindSceneServices();
            if (native_script_walk_runtime)
                native_script_walk_runtime->UnbindNpcScene();
            native_script_player_action->UnbindNpcScene();
            if (native_script_talk) native_script_talk->ClearHandlers();
            native_script_talk.reset();
            native_sound_2d.reset();
            native_script_system_ui.reset();
            UnbindNativeActorSceneEvents();
            Check(SetNativeSceneHudVisible(false), "scene reload hides HUD before releasing player actions");
            // This adapter borrows the application PlayerManager, not scene assets.
            // Keep it valid for B4's intermediate Scene entry after arena release.
            native_script_player_walk.reset();
            if (native_script_walk_runtime) native_script_walk_runtime->ClearHandlers();
            native_script_walk_runtime.reset();
        };
        const auto after_players = [&] {
            native_random_player_position.reset();
            native_script_player_position.reset();
            if (native_script_player_turn) native_script_player_turn->ClearHandlers();
            if (native_npc_blend) native_npc_blend->ClearHandlers();
            native_script_player_turn.reset();
            native_npc_blend.reset();
            if(native_script_monster_blend)native_script_monster_blend->ClearHandlers();
            native_script_monster_blend.reset();
            native_script_player_rotation.reset();
            if (native_object_effects) native_object_effects->ClearHandlers();
            native_object_touch.reset();
            native_object_effects.reset();
            native_script_object_visibility.reset();
            native_script_npc_visibility.reset();
            native_script_npc_material.reset();
            native_script_monster_visibility.reset();
            native_script_monster_pursuit.reset();
            native_script_player_lock.reset();
            native_script_camera_mode.reset();
            native_script_camera.reset();
            native_camera_sequences.reset();
            native_arena_ready.reset();
            // Snapshot actor paths while NPC storage is still alive.
            Check(!verify_story_fixture || scene_npcs->EnteredCount() ==
                      (leaving_q01 ? 4u : 1u),
                  "current NPC scene membership survives until ordered leave");
            native_script_path_allocations = 0u;
            for(const auto& slot:native_player_session->State().slots) {
                const auto& path_actor=*reinterpret_cast<const pal4::CollisionActorState*>(
                    reinterpret_cast<std::uintptr_t>(&slot.base)+0x564u);
                native_script_path_allocations += path_actor.words[22u];
            }
            native_script_npc_path_allocations = 0u;
            for (const auto name : {"MN001", "MN002", "MN003", "MN004"}) {
                const auto npc = scene_npcs->Manager()
                    .FindObject(name);
                if (!npc) continue;
                const auto& npc_path =
                    *reinterpret_cast<const pal4::CollisionActorState*>(
                        static_cast<std::uintptr_t>(npc + 0x564u));
                native_script_npc_path_allocations += npc_path.words[22u];
            }
            allocations_before_actor_release = native_player_memory.OutstandingAllocations();
            Check(!verify_story_fixture || native_scene_gob_assets.Size() ==
                      (leaving_q01 ? 48u : 4u),
                  "current scene objects remain owned before leave");
        };
        // Host script/cloud objects are opaque receiver identities, not forged
        // VC6 object images. The adapter validates their callback-only tokens.
        const auto script_identity=reinterpret_cast<std::uint32_t>(native_script_session.get());
        const auto cloud_identity=reinterpret_cast<std::uint32_t>(native_camera_sequences.get());
        const auto actor_identity=native_actor_session->Address();
        const auto player_identity=reinterpret_cast<std::uint32_t>(&native_player_session->State());
        const auto pet_identity=native_pet->Address();
        const auto camera_identity=native_camera_manager->Address();
        class Gameplay final : public pal4::IGameArenaReleaseRuntime {
        public:
            using Dispatch=std::function<std::uint32_t(pal4::GameArenaReleaseCall,std::uint32_t,std::uint32_t,std::uint32_t)>;
            explicit Gameplay(Dispatch dispatch):dispatch_(std::move(dispatch)) {}
            std::uint32_t ReadWord(std::uint32_t) override { Unsupported(); }
            void WriteWord(std::uint32_t,std::uint32_t) override { Unsupported(); }
            std::string_view ReadCString(std::uint32_t) override { Unsupported(); }
            void StoreText(std::uint32_t,std::string_view) override { Unsupported(); }
            std::uint32_t Call(pal4::GameArenaReleaseCall op,std::uint32_t first,
                std::uint32_t second,std::uint32_t third) override { return dispatch_(op,first,second,third); }
        private:
            [[noreturn]] static void Unsupported() { throw std::logic_error("gameplay release has no raw storage"); }
            Dispatch dispatch_;
        } gameplay([&](pal4::GameArenaReleaseCall op,std::uint32_t first,std::uint32_t second,std::uint32_t third) -> std::uint32_t {
            using Op=pal4::GameArenaReleaseCall;
            Check(!third,"full release gameplay third argument");
            const auto receiver=[&](std::uint32_t expected,bool visits=false) {
                Check(first==expected && second==(visits?native_arena_manager->Address():0u),
                      "full release gameplay creating-owner receiver");
            };
            switch(op) {
            case Op::GetScriptExecutor: receiver(0u); return script_identity;
            case Op::CleanupLogHandlers:
                receiver(script_identity+0x54u);
                native_script_session->ClearSceneWaitHandlers([this] { ClearNativeScriptHandlers(); });
                break;
            case Op::ResetScriptExecutor:
                receiver(script_identity);
                native_script_session->ResetSceneQueues();
                if(native_sound_2d) native_sound_2d->ResetScriptData();
                native_script_session->Timer().DisableForSceneRelease();
                break;
            case Op::GetScriptCloudManager: receiver(0u); return cloud_identity;
            case Op::CleanupCameraTree:
                receiver(cloud_identity);
                if(native_camera_sequences) native_camera_sequences->ResetSceneSequences();
                break;
            case Op::GetCameraSubsystem: receiver(0u); return camera_identity;
            case Op::CleanupCameraProperties:
                receiver(camera_identity);
                native_camera_manager->ResetSceneProperties();
                Check(native_camera_manager->State().At(0x30u)==native_camera_manager->State().At(0x34u),
                      "full release restores MainCamera before actor leave");
                Check(native_script_session->Status()==primary && native_script_session->EventStatus()==event &&
                          native_script_session->GlobalStoryVariable()==story,
                      "full release preserves suspended script contexts and story");
                detach_borrowers();
                break;
            case Op::GetActorControl: receiver(0u); return actor_identity;
            case Op::ClearActor: receiver(actor_identity); ClearNativeSceneActorControl(); break;
            case Op::GetPlayerManager: receiver(0u); return player_identity;
            case Op::ForAllPlayers: receiver(player_identity,true); LeaveNativeScenePlayers(false); break;
            case Op::UpdatePlayers:
                receiver(player_identity);
                pal4::NativeArenaPlayerSceneEntry::UpdateData(native_player_session->State(),native_player_materials.get());
                break;
            case Op::RemovePetScript:
                receiver(native_arena_manager->Address());
                if(native_pet_scene) return native_pet_scene->Remove();
                break;
            case Op::GetPetManager: receiver(0u); return pet_identity;
            case Op::CleanupPets:
                receiver(pet_identity); ClearNativeSceneEffects(); after_players(); break;
            default: throw std::logic_error("full arena gameplay release operation is not bound");
            }
            return 0u;
        });
        pal4::NativeArenaReleaseRuntime runtime(*native_arena_manager,*native_scene_effects,
            *native_arena_scene_stage, {
                native_arena_manager->Address(), *scene_npcs,
                native_monster_scene_entry, *native_monster_manager,
                native_scene_gob_assets, native_second_scene_gob_entry,
                native_scene_evf_assets, *native_path_planner,
                native_arena_scene_stage->Movement(), *native_camera_manager,
                [this] { native_minimap_manager->RefreshObjectSprites(native_scene_gob_assets); },
                game.Address(), *native_player_materials, *native_game_texture_storage
            }, gameplay, [&](pal4::GameArenaReleaseCall operation) {
            using Op=pal4::GameArenaReleaseCall;
            switch(operation) {
            case Op::ForAllNpcs:
                Check(scene_npcs->EnteredCount()==0u &&
                          scene_npcs->Manager().Address()!=0u,
                      "ordered NPC leave preserves manager until cleanup");
                break;
            case Op::CleanupNpcs:
                if(opening) ReleaseOpeningNpcProbe();
                std::cout << "Scene NPC release: objects=" << scene_npcs->Count()
                          << " entered=" << scene_npcs->EnteredCount()
                          << " atomics=" << native_arena_scene_stage->Movement().RegisteredObjectAtomics()
                          << " manager=" << scene_npcs->Manager().Address()
                          << " allocations=" << scene_npcs->Manager().OutstandingAllocations() << '\n';
                Check(scene_npcs->Count() == 0u &&
                          scene_npcs->EnteredCount() == 0u &&
                          native_arena_scene_stage->Movement()
                                  .RegisteredObjectAtomics() == 0u &&
                          scene_npcs->Manager().Address() != 0u &&
                          scene_npcs->Manager().ObjectCount() == 0u &&
                          scene_npcs->Manager().InfoCount() == 0u &&
                          scene_npcs->Manager().GridAddress() == 0u,
                      "current NPCs release before Loading");
                break;
            case Op::CleanupMonsters:
                Check(native_monster_manager->Address() != 0u &&
                          native_monster_manager->ObjectCount() == 0u &&
                          native_monster_manager->InfoCount() == 0u &&
                          native_monster_manager->GridAddress() == 0u,
                      "monster scene cleanup retains empty manager before return Loading");
                Check(native_player_memory.OutstandingAllocations() <= allocations_before_actor_release,
                      "NPC and monster release cannot grow player-owned storage");
                retired_actor_allocations = allocations_before_actor_release -
                    native_player_memory.OutstandingAllocations();
                break;
            case Op::ForAllObjects:
                if (native_scene_gob_entered) {
                    auto* object = native_scene_gob_assets.FindMutableObject("MO001");
                    const auto* model = native_scene_gob_assets.FindModel("MO001");
                    Check(object && model, "active GOB teardown target");
                    std::uint32_t restored_callback = 0u;
                    Check(RpClumpForAllAtomics(
                              model->Clump(),
                              [](RpAtomic* atomic, void* output) {
                                  *static_cast<std::uint32_t*>(output) =
                                      reinterpret_cast<std::uint32_t>(
                                          RpAtomicGetRenderCallBack(atomic));
                                  return atomic;
                              }, &restored_callback) == model->Clump() &&
                              restored_callback ==
                                  native_gob_original_render_callback,
                          "GOB scene teardown restores the original Atomic callback");
                    Check(native_player_memory.ReadDword(
                              object->Address() + 0x184u) == 0u &&
                              RpClumpGetWorld(model->Clump()) == nullptr &&
                              native_arena_scene_stage->Movement()
                                      .RegisteredObjectAtomics() == 0u,
                          "GOB scene leave releases visibility, movement and world");
                    native_scene_gob_entered = false;
                }
                Check(native_second_scene_gob_entry.Count() == 0u &&
                          native_arena_scene_stage->Movement()
                                  .RegisteredSecondaryObjectAtomics() == 0u,
                      "current scene GOBs release secondary movement bindings");
                gob_allocations_before_clear =
                    native_player_memory.OutstandingAllocations();
                break;
            case Op::CleanupObjects:
                Check(native_scene_gob_assets.ManagerAddress()!=0u &&
                          native_scene_gob_assets.FactoryCount()==11u &&
                          native_player_memory.ReadDword(native_scene_gob_assets.ManagerAddress()+12u)==0u,
                      "full arena release retains the actual empty GOB manager and factories");
                native_scene_gob_assets.ActivateAll();
                native_scene_gob_assets.DeactivateAll();
                Check(native_scene_gob_assets.Size() == 0u &&
                          (native_player_memory.OutstandingAllocations() < gob_allocations_before_clear ||
                           (!verify_story_fixture && gob_allocations_before_clear ==
                               native_player_memory.OutstandingAllocations())) &&
                          (!verify_story_fixture || !leaving_q01 || native_q01_exit_count != 0u ||
                           native_player_memory.OutstandingAllocations() ==
                               native_second_scene_gob_memory_before +
                                   native_scene_gob_assets.RetainedManagerAllocations() +
                                   native_script_path_allocations +
                                   native_script_npc_path_allocations - retired_actor_allocations),
                      "current GOB images release after NPC and monster owners");
                break;
            case Op::ForAllSecondaryObjects:
                if (native_scene_evf_entered) {
                    Check(native_camera_manager->SceneClumpCount() == 0u &&
                              native_arena_scene_stage->Movement()
                                      .RegisteredSecondaryObjectAtomics() == 0u &&
                              native_arena_scene_stage->Movement()
                                      .RegisteredObjectAtomics() == 0u,
                          "EVF scene teardown releases Movement bindings");
                    native_scene_evf_entered = false;
                }
                break;
            case Op::CleanupSecondaryObjects:
                Check(native_scene_evf_assets.Size() == 0u,
                      "Q01/Q01 exit events release before return Loading");
                break;
            case Op::CleanupPaths:
                Check(native_path_planner->OutstandingAllocations() == 0u,
                      "Q01/Q01 path planner releases before return Loading");
                native_scene_player_movement->DetachScene();
                Check(!native_scene_player_movement->FloorAtomic() &&
                          native_scene_player_movement->FloorTriangle() == -1 &&
                          native_temperature_manager->Address() != 0u &&
                          native_floor_attribute->State().list_size == 5u,
                      "scene release detaches borrowed floor hits and retains temperature callbacks");

                Check(native_arena_scene_stage->Movement()
                          .RegisteredObjectAtomics() == 0u,
                      "current scene movement releases player registrations");
                UnbindNativeActorSceneEvents();
                Check(SetNativeSceneHudVisible(false), "scene replacement hides persistent HUD before releasing scene contents");
                // The registered UI frame outlives its scene contents, including
                // B4's released Scene entry. Keep its identity for the next scene.

                break;
            default: break;
            }
        });
        Check(native_arena_manager->ReleaseScene(runtime),"full shared arena release completes a loaded scene");
        native_arena_scene_stage->CompleteRelease();
        Check(!native_arena_world.World() &&
                  !runtime.ReadWord(native_arena_manager->Address()+264u) &&
                  !runtime.ReadWord(native_arena_manager->Address()+424u) &&
                  !native_arena_manager->ReleaseScene(runtime),
              "full arena release retires world/Scene/pipeline and repeats through the original empty-world gate");
        Check(!verify_story_fixture || !leaving_q01 || native_q01_exit_count != 0u ||
                  native_player_memory.OutstandingAllocations() ==
                      native_scene_gob_memory_before +
                          native_player_animation_memory_retained +
                          native_scene_gob_assets.RetainedManagerAllocations() +
                          native_script_path_allocations,
              "ordered scene object release preserves exact allocation baseline");
        Check(scene_npcs->Manager().Address() == native_scene_npc_manager_identity &&
                  scene_npcs->Manager().TreeGlobals().nil_address == native_scene_npc_manager_nil &&
                  scene_npcs->Count() == 0u && scene_npcs->EnteredCount() == 0u,
              "full release preserves NPC singleton and tree nil after world retirement");
        scene_npcs->Manager().SetGridUpdating(false);
        // IDA51B270 retains the singleton: B4's intermediate Scene still calls
        // 58F0B0's collision pass after the world/collision tree has retired.
        pal4::NativeMonsterPursuitPathRuntime empty_monster_paths(
            *native_monster_manager, native_arena_scene_stage->CollisionTree(),
            native_player_memory);
        Check(native_monster_manager->Address() == native_monster_manager_identity &&
                  native_monster_manager->ObjectCount() == 0u &&
                  native_monster_manager->InfoCount() == 0u &&
                  !native_monster_manager->GridAddress() &&
                  native_monster_manager->ProcessCollisions(0.1f, &empty_monster_paths) != 0u,
              "released world retains monster singleton for actual empty Scene collision dispatch");
        native_path_planner.reset();
        std::cout << (opening ? "Opening scene: " : "Reloaded scene: ") << "Native full arena release: shared51B270 through scoped owner lifecycle, world and pipeline retired\n";
    }
    std::uint32_t AdvancePendingReloadedSceneLoading(
        std::string_view destination) {
        Check(PendingFrameSceneSwitch() &&
                  (native_arena_manager->SceneName() == "Q01" ||
                   native_arena_manager->SceneName() == "N01") &&
                  native_loading_state->String(12u) == "Q01" &&
                  native_loading_state->String(24u) == destination &&
                  native_script_session->EventStatus() ==
                      pal4::NativeScriptFrameStatus::suspended,
              "reloaded scene switch requires a suspended event Loading request");
        const bool leaving_q01 = native_arena_manager->SceneName() == "Q01";
        ReleaseCurrentSceneForTransition(true);
        const bool minimap_loaded = leaving_q01
            ? native_minimap_manager->LoadSceneWithoutLayers(
                  config_path->parent_path(), "Q01", destination)
            : native_minimap_manager->LoadScene(
                  config_path->parent_path(), "Q01", destination);
        Check(minimap_loaded &&
                  (!leaving_q01 || native_minimap_manager->ActiveIcon() == 0u),
              "current minimap prepares the target scene");
        EnsureNativeSceneHudOwner();
        // Exercise both explicit diff and the empty/default path through real
        // scene services. The production Loading runtime forwards this field.
        if (!play_mode) native_loading_state->AssignString(36u, destination);
        const auto result = AdvanceNativeLoadingWithPresentation();
        if (!leaving_q01) {
            Check(result == 0u && !native_arena_load->LoadingActive() &&
                      native_arena_manager->SceneName() == "Q01" &&
                      native_script_session->EventStatus() ==
                          pal4::NativeScriptFrameStatus::suspended,
                  "N01 entrance restores Q01 with suspended func1002");
            return result;
        }
        Check(result == 0u && !native_arena_load->LoadingActive() &&
                  native_arena_scene_stage->CollisionTree().FaceCount() == 105 &&
                  native_script_session->EventStatus() ==
                      pal4::NativeScriptFrameStatus::suspended,
              "Q01 exit restores N01 and preserves suspended func1001");
        native_script_player_action->BindNpcScene(*native_second_scene_npcs);
        native_random_player_position.reset();
        native_script_player_position =
            std::make_unique<pal4::NativeScriptPlayerPositionRuntime>(
                *native_player_session, native_player_transforms);
        native_script_player_position->BindAnimations(*native_player_animations);
        native_script_player_position->BindNpcs(native_second_scene_npcs.get());
        native_script_player_position->BindMovement(
            *native_scene_player_movement);
        native_script_player_position->BindFloorColor(*native_floor_attribute);
        native_script_player_position->BindGrid(*native_minimap_manager);
        native_script_player_position->BindAnimation(
            *native_player_animation_binding);
        native_script_camera_mode =
            std::make_unique<pal4::NativeScriptCameraModeRuntime>(
                *native_camera_manager, *native_actor_session,
                *native_player_session);
        native_script_camera =
            std::make_unique<pal4::NativeScriptCameraRuntime>(
                *native_camera_manager, *native_player_session);
        native_script_camera->BindLookAt(
            [this](std::uint32_t object, std::uint32_t option) {
                native_script_camera_mode->SetLookAt(object, option);
            });
        native_script_camera->BindListener(native_silent_camera_listener);
        native_script_player_position->BindCamera(*native_script_camera);
        native_script_player_rotation =
            std::make_unique<pal4::NativeScriptPlayerRotationRuntime>(
                *native_player_session, native_player_transforms);
        native_script_player_rotation->BindNpcs(native_second_scene_npcs.get());
        native_script_player_lock =
            std::make_unique<pal4::NativeScriptPlayerLockRuntime>(
                *native_player_session, *native_actor_session, ActiveInput(),
                *native_monster_manager, SceneUiEvents(), *this);
        native_script_player_lock->BindAnimation(
            *native_player_animation_binding);
        native_script_player_lock->BindMinimap(*native_minimap_manager);
        native_arena_ready =
            std::make_unique<pal4::NativeArenaReadyRuntime>(
                *native_arena_manager, *native_actor_session,
                *native_player_session, game, *this, *native_pet);
        Check(native_arena_ready->PetManager() == native_pet->Address(),
              "scene reentry preserves the application pet identity");
        native_arena_ready->BindMinimap(*native_minimap_manager);
        native_arena_ready->BindHints(native_scene_hints);
        Check(native_script_player_actions != nullptr,
              "scene reentry retains the application player actions adapter");
        native_script_session->RebindSuspendedEventServices(EventServices());
        BindQueuedSceneInit();
        RestoreNativeLoadedSceneUi();
        ++native_q01_exit_count;
        return result;
    }
    std::uint32_t AdvancePendingReturnLoading() {
        Check(native_arena_manager->SceneName() == "Q01" &&
                  native_loading_state->String(24u) == "N01",
              "Q01 exit targets N01");
        return AdvancePendingReloadedSceneLoading("N01");
    }
    // The first N01 fixture keeps Loading open while scripted setup runs.
    pal4::NativeComparisonScriptState ComparisonScripts() const {
        pal4::NativeComparisonScriptState result;
        if(native_game_texture_storage) {
            result.global_variables.resize(48u);
            for(std::uint32_t i=0;i<result.global_variables.size();++i)
                result.global_variables[i]=*reinterpret_cast<const std::int32_t*>(
                    native_game_texture_storage->GlobalAddress(0x90dec0u+i*4u));
        }
        result.inventory_address=native_inventory.Address();
        result.gob_manager_address=native_scene_gob_assets.ManagerAddress();
        if(const auto* npcs=CurrentSceneNpcs())result.npc_manager_address=npcs->Manager().Address();
        if(native_monster_manager)result.monster_manager_address=native_monster_manager->Address();
        if(result.inventory_address)result.money=*reinterpret_cast<const std::int32_t*>(result.inventory_address+0x134u);
        if(native_common_dialog_cache)
            if(const auto dialog=native_common_dialog_cache->Find())
                result.common_dialog_address=dialog->FrameAddress();
        if(native_select_dialog)result.select_dialog_address=native_select_dialog->FrameAddress();
        if(native_world_map)result.world_map_address=native_world_map->FrameAddress();
        if(native_settings){
            const auto& state=native_settings->State();
            for(auto node=native_settings->FirstNode(state,116u);node!=state.Word(120u);node=native_settings->NextNode(node,true))
                result.opened_object_events.push_back(native_settings->NodeValue(node));
        }
        if(native_arena_manager){
            result.world=native_arena_manager->LoadedWorldName();
            result.scene=native_arena_manager->SceneName();
            result.arena_ready=native_arena_manager->ReadyFlag();
        }
        result.pending_scene=PendingFrameSceneSwitch();
        if(native_arena_load){
            result.logo_active=native_arena_load->LogoActive();
            result.loading_active=native_arena_load->LoadingActive();
            result.scene_active=native_arena_load->SceneActive();
        }
        result.scene_world=reinterpret_cast<std::uint32_t>(native_arena_world.World());
        const auto& fade=native_screen_effect.render;
        result.fade_phase=fade.phase;result.fade_active=fade.active;
        result.fade_elapsed=fade.elapsed;result.fade_duration=fade.duration;
        result.fade_alpha=fade.alpha;result.fade_color={fade.red,fade.green,fade.blue};
        result.loading_visible=native_loading_window_visible;
        result.loading_presented=native_loading_frames_presented;
        result.fade_draw_calls=native_fade_draw_calls;
        if(!native_script_session)return result;
        result.scene_depth=static_cast<std::uint32_t>(native_script_session->ConcurrentSceneDepth());
        result.timed_active=native_script_session->TimedScriptsActive();
        const auto blocked=[](const auto& owner){return owner && owner->BlocksScript();};
        const auto capture=[&](const char* name,auto status,asIScriptContext& context,
                               const ContextExecution* owner){
            std::uint32_t waits=0;
            if(owner){
                waits=(blocked(owner->waits)?1u:0u)|(blocked(owner->flash)?2u:0u)|
                    (owner->movie && (owner->movie->Waiting() || owner->movie->CompletionPending())?4u:0u)|(blocked(owner->timer)?8u:0u)|
                    (blocked(owner->action)?16u:0u)|(blocked(owner->turn)?32u:0u)|
                    (blocked(owner->walk_runtime)?64u:0u)|(blocked(owner->blend)?128u:0u)|
                    (blocked(owner->object_effects)?256u:0u)|(blocked(owner->talk)?512u:0u)|
                    (blocked(owner->camera)?1024u:0u);
            }else if(std::string_view(name)=="root"){
                waits=(blocked(native_opening_wait)?1u:0u)|(blocked(native_flash)?2u:0u)|
                    (blocked(native_timed_wait)?8u:0u)|(blocked(native_camera_sequences)?1024u:0u);
            }
            result.contexts.push_back({name,static_cast<std::uint32_t>(status),waits,
                static_cast<std::int32_t>(context.GetState()),context.GetCurrentLineNumber(),
                reinterpret_cast<std::uint32_t>(&context),context.GetCurrentFunction(),
                owner && owner->action ? static_cast<std::uint32_t>(owner->action->WaitQueue()->Size()) : 0u,
                owner && owner->action && owner->action->WaitQueue()->BlocksScript() ? 1u : 0u,
                owner && owner->action ? static_cast<std::uint32_t>(owner->action->ActiveActionCount()) : 0u});
        };
        capture("root",native_script_session->Status(),native_script_session->Context(),nullptr);
        capture("event",native_script_session->EventStatus(),native_script_session->EventContext(),native_event_execution.get());
        if(result.scene_depth)capture("scene",native_script_session->ConcurrentSceneStatus(),
            native_script_session->ConcurrentSceneContext(),native_scene_init_execution.get());
        return result;
    }
    bool PendingFrameSceneSwitch() const {
        return native_arena_load && native_arena_load->LoadingScenePending() &&
            native_loading_scene_loaded && native_arena_manager &&
            native_loading_state &&
            (native_loading_state->String(12u) != native_arena_manager->LoadedWorldName() ||
             native_loading_state->String(24u) != native_arena_manager->SceneName());
    }
    bool AdvancePendingReturnSceneIfReady() {
        if (!native_second_scene_advanced_in_frame ||
            !PendingFrameSceneSwitch() ||
            native_arena_manager->SceneName() != "Q01" ||
            native_loading_state->String(12u) != "Q01" ||
            native_loading_state->String(24u) != "N01")
            return false;
        return AdvancePendingReturnLoading() == 0u;
    }
