                std::uint32_t other_dds = 0u;
                std::uint32_t raw_dxt5_transparent_textures = 0u;
                std::uint32_t raw_dxt5_transparent_atomics = 0u;
                std::uint32_t raw_dxt5_parse_failures = 0u;
                std::uint32_t compressed_raster_locks = 0u;
