                    queue.Update(0.3f);
                    Check(fired == 0u, "HUD stats does not fire at equal remaining time");
                    queue.Update(0.001f);
                    Check(fired == 1u, "HUD stats timer fires after original 0.3-second threshold");
                    pal4::ConfigureNativeSceneHudStatsTimer(queue, owner, true);
                    queue.Update(0.0f);
