            const auto script_before = script_data;
            const auto script_yaw = yaw_runtime.ReadCameraYaw(script_internal);
            const auto script_pitch = std::bit_cast<float>(script_data.At(0x40u));
            const auto control_before_script_camera = native_actor_session->State();
