            Check(drag_probe.updates == 3u &&
                      native_actor_session->State().words[14u] == 0u &&
                      restored_angles.yaw == yaw_before &&
                      restored_angles.pitch == pitch_before,
                  "ActorControl drag release restores angles and look-at");
            yaw_input.WriteDword(0x1ed8u, 0u);
            yaw_input.WriteDword(0x1ee0u, 0u);
